// ---- Google Maps sob demanda ----
function loadGoogleMaps(key) {
  if (window.google && window.google.maps && window.google.maps.Map) return Promise.resolve();
  function waitForMaps(ms) {
    return new Promise((resolve, reject) => {
      const t = Date.now();
      const check = () => {
        if (window.google && window.google.maps && window.google.maps.Map) return resolve();
        if (Date.now() - t > ms) return reject(new Error('Timeout aguardando Google Maps inicializar'));
        setTimeout(check, 150);
      };
      check();
    });
  }
  if (document.getElementById('gmaps-script')) return waitForMaps(12000);
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.id = 'gmaps-script';
    s.src = 'https://maps.googleapis.com/maps/api/js?key=' + key + '&libraries=geometry&v=weekly';
    s.async = true;
    s.onerror = () => reject(new Error('Falha ao carregar script do Google Maps'));
    s.onload = () => waitForMaps(10000).then(resolve).catch(reject);
    document.head.appendChild(s);
  });
}

