function renderTable(rota) {
  const tbody = document.getElementById('passTable');
  if (!tbody) return;
  tbody.innerHTML = '';

  const sorted = [...rota.passageiros].sort((a, b) => {
    const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
    const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
    return ta.localeCompare(tb);
  });

  const statusMap   = { ativo: 'status-ativo', ferias: 'status-ferias', afastado: 'status-afastado', desligado: 'status-desligado' };
  const statusLabel = { ativo: 'Ativo', ferias: 'Férias', afastado: 'Afastado', desligado: 'Desligado' };

  sorted.forEach((p, seqIdx) => {
    const realIdx = rota.passageiros.indexOf(p);
    const embarque = p.embarque || p.endereco;
    const retornoFmt = p.retorno ? (() => {
      // Convert YYYY-MM-DD to DD/MM/YYYY if needed
      const m = p.retorno.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      return m ? m[3]+'/'+m[2]+'/'+m[1] : p.retorno;
    })() : '';
    const retornoBadge = (p.retorno && (p.status === 'ferias' || p.status === 'afastado'))
      ? '<span class="retorno-badge">↩ ' + retornoFmt + '</span>' : '';

    const tr = document.createElement('tr');
    if (p.status === 'desligado') tr.style.opacity = '0.5';
    tr.innerHTML =
      '<td class="td-order">' + (seqIdx + 1) + '</td>' +
      '<td class="td-time">' + (p.horario || '--:--') + '</td>' +
      '<td><div class="td-name" style="' + (p.status==='ferias'||p.status==='afastado' ? 'color:var(--red);opacity:0.85' : '') + '">' + p.nome + '</div><div class="td-sub">' + (p.cidade || '') + '</div></td>' +
      '<td style="font-size:12px;color:var(--muted);white-space:nowrap">' + (p.telefone || '—') + '</td>' +
      '<td class="td-addr"><div>' + (embarque || '—') + '</div>' +
        (p.embarque && p.endereco && p.embarque !== p.endereco ? '<div class="td-addr-embarque">' + p.endereco + '</div>' : '') +
      '</td>' +
      '<td style="font-size:12px;color:var(--muted)">' + (p.bairro || '—') + '</td>' +
      '<td style="' + (p.status==='ferias'||p.status==='afastado' ? 'color:var(--red)' : '') + '"><span class="status-badge ' + (statusMap[p.status] || 'status-ativo') + '"><span class="dot"></span>' + (statusLabel[p.status] || 'Ativo') + '</span>' + retornoBadge + '</td>' +
      '<td class="actions-td"></td>';

// View only - no edit buttons

    // Fase 1.5: as setas de reordenacao foram removidas do portal do cliente.
    // Elas chamavam movePassageiro(), que nunca existiu neste engine, e alterar
    // horario de embarque nao e atribuicao do cliente (a tela e de visualizacao).
    // A reordenacao vive no painel do gestor.

    tbody.appendChild(tr);
  });
}

