// ---- EXPORT EXCEL ----
function exportExcel() {
  const wb = XLSX.utils.book_new();

  // Sheet 1: All passengers
  const allRows = [['Linha','Turno','Motorista','Veículo','#Embarque','Nome','Horário','Endereço','Ponto Embarque','Bairro','Cidade','Telefone','Status','Retorno']];
  DATA.forEach(rota => {
    const sorted = [...rota.passageiros].sort((a,b) => {
      const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
      const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
      return ta.localeCompare(tb);
    });
    sorted.forEach((p, i) => {
      allRows.push([
        rota.linha, rota.turno, rota.motorista, rota.veiculo,
        i+1, p.nome, p.horario, p.endereco, p.embarque,
        p.bairro, p.cidade, p.telefone, p.status, p.retorno || ''
      ]);
    });
  });
  const ws1 = XLSX.utils.aoa_to_sheet(allRows);
  ws1['!cols'] = [4,6,10,6,4,20,6,22,22,12,10,12,8,10].map(w => ({wch:w}));
  XLSX.utils.book_append_sheet(wb, ws1, 'Passageiros');

  // Sheet 2: Desligados
  if (DESLIGADOS.length > 0) {
    const desRows = [['Nome','Linha Origem','Turno','Telefone','Endereço','Bairro','Cidade']];
    DESLIGADOS.forEach(p => desRows.push([p.nome, p.linhaOrigem, p.turnoOrigem, p.telefone, p.endereco, p.bairro, p.cidade]));
    const ws2 = XLSX.utils.aoa_to_sheet(desRows);
    XLSX.utils.book_append_sheet(wb, ws2, 'Desligados');
  }

  // Sheet 3: Motoristas
  const motoRows = [['Nome','Telefone','Linhas Atribuídas']];
  MOTORISTAS.forEach(m => {
    const linhas = DATA.filter(r => r.motorista === m.nome).map(r => 'L' + r.linha + ' ' + r.turno).join(', ');
    motoRows.push([m.nome, m.tel, linhas]);
  });
  const ws3 = XLSX.utils.aoa_to_sheet(motoRows);
  XLSX.utils.book_append_sheet(wb, ws3, 'Motoristas');

  // Sheet 4: Relatório de alterações
  if (changeLog.length > 0) {
    const logRows = [['Data','Hora','Tipo','Nome','De','Para','Observação']];
    const tipoLabel = { inclusao:'Inclusão', desligamento:'Desligamento', alteracao:'Alteração', transferencia:'Transferência', status:'Mudança de Status' };
    changeLog.forEach(l => logRows.push([l.dia, l.hora, tipoLabel[l.tipo]||l.tipo, l.nome, l.de, l.para, l.extra||'']));
    const ws4 = XLSX.utils.aoa_to_sheet(logRows);
    ws4['!cols'] = [10,6,14,20,24,24,20].map(w => ({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws4, 'Relatório Alterações');
  }

  // Sheet 5: Resumo por linha
  const resumoRows = [['Linha','Turno','Motorista','Telefone Motorista','Veículo','Total Passageiros','Capacidade','Vagas Livres']];
  DATA.forEach(rota => {
    const m = MOTORISTAS.find(x => x.nome === rota.motorista);
    const cap = rota.veiculo === 'Carro' ? 4 : 15;
    resumoRows.push([rota.linha, rota.turno, rota.motorista, m ? m.tel : '', rota.veiculo, rota.passageiros.length, cap, cap - rota.passageiros.length]);
  });
  const ws5 = XLSX.utils.aoa_to_sheet(resumoRows);
  XLSX.utils.book_append_sheet(wb, ws5, 'Resumo por Linha');

  const hoje = new Date().toLocaleDateString('pt-BR').replace(/\//g,'-');
  XLSX.writeFile(wb, 'TransportManager_' + hoje + '.xlsx');
}



