function pdfDiasVariantes(turno) {
  if (typeof turnoPorNome !== 'function') return [];
  const t = turnoPorNome(turno);
  if (!t) return [];
  const padrao = t.chegada || (TURNOS_CHEGADA || {})[turno] || '';
  const out = [];
  DIAS_SEMANA.forEach(d => {
    const r = t.dias && t.dias[d];
    if (!r || r === false) return;                    // nao opera: nao e coluna
    const ch = r.chegada || '';
    if (!ch || ch === padrao) return;                 // igual ao padrao: nao informa
    out.push({ dia: d, nome: DIAS_NOME[d], chegada: ch,
               alternado: !!(t.alternado && t.alternado.dia === d),
               alt: t.alternado });
  });
  return out;
}

// Desloca o horario do passageiro para aquele dia.
function pdfHoraVariante(horario, turno, chegadaDoDia) {
  const base = otHmToMin(horario);
  const cd = otHmToMin(chegadaDoDia);
  const cp = otHmToMin((TURNOS_CHEGADA || {})[turno] || '');
  if (base == null || cd == null || cp == null) return horario || '--:--';
  return otHHMM(base + (cd - cp));
}

async function exportPDF(rotaId, dataPdf) {
  const { jsPDF } = window.jspdf;
  if (!jsPDF) { alert('Biblioteca PDF não carregou ainda. Tente novamente.'); return; }

  await pdfCarregarLogo();

  const targetIds = rotaId ? [rotaId] : (activeId ? [activeId] : DATA.map(r => r.id));

  for (const rid of targetIds) {
    const rota = DATA.find(r => r.id === rid);
    if (!rota) continue;

    if (!pdfRevision[rid]) pdfRevision[rid] = 0;
    pdfRevision[rid]++;
    const rev = pdfRevision[rid];

    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const now = new Date();
    const datahora = now.toLocaleDateString('pt-BR') + ' ' +
      now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

    const nomeOperacao = (EMPRESA_CONFIG.operacaoNome || '').trim() ||
      (C.pathPrefix || '').split('/').filter(Boolean).pop().toUpperCase();
    const ctx = {
      transportadora: EMPRESA_CONFIG.nome || C.empresaNome || C.marca,
      operacao: nomeOperacao,
      tituloLinha: 'Linha ' + rota.linha + ' — ' + rota.turno + ' Turno'
    };

    const L = 14, R = 196;
    let y = pdfCabecalho(doc, ctx, true);

    // ---- título + data de geração ----
    doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text('Relatório de Embarque', L, y + 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.setTextColor.apply(doc, PDF_COR.texto);
    doc.text('Relação de passageiros e pontos de embarque', L, y + 12.5);

    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.setFillColor(255, 255, 255);
    doc.roundedRect(R - 58, y - 2, 58, 16, 2, 2, 'FD');
    pdfIcone(doc, 'calendario', R - 53, y + 3, 6.4);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Gerado em', R - 44, y + 4.5);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(datahora, R - 44, y + 10.5);
    if (dataPdf) {
      doc.setFontSize(9); doc.setTextColor.apply(doc, PDF_COR.destaque);
      doc.text(pdfDiaSemanaBr(dataPdf) + ' · ' + pdfDataBr(dataPdf), L, y + 10.5);
      doc.setTextColor.apply(doc, PDF_COR.texto);
    }
    y += 20;

    // ---- cartão da linha ----
    // A chegada do DIA, nao a padrao.
    const _tDia = (dataPdf && typeof turnoNoDia === 'function')
      ? turnoNoDia(rota.turno, dataPdf) : null;
    const chegada = (_tDia && _tDia.opera && _tDia.chegada) || TURNOS_CHEGADA[rota.turno] || '—';
    // Linha que nao opera no dia nao vira PDF: imprimir uma rota que nao
    // existe e pior do que nao imprimir nada.
    if (_tDia && !_tDia.opera) {
      alert('Linha ' + rota.linha + ' · ' + rota.turno + ' não opera em ' +
            pdfDataBr(dataPdf) + '.\n\n' + (_tDia.motivo || ''));
      continue;
    }
    const motor = rota.motorista || 'A definir';
    const mObj = MOTORISTAS.find(m => m.nome === motor);
    doc.setFillColor.apply(doc, PDF_COR.fundo);
    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.roundedRect(L, y, R - L, 24, 3, 3, 'FD');

    doc.setDrawColor.apply(doc, PDF_COR.ambar); doc.setLineWidth(0.5);
    doc.circle(L + 12, y + 12, 7, 'S');
    pdfIcone(doc, 'van', L + 8, y + 8, 8);

    doc.setFont('helvetica', 'bold'); doc.setFontSize(14);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(ctx.tituloLinha, L + 24, y + 8);

    // Larguras por campo, nao divisao igual: telefone e veiculo precisam de mais
    // espaco que "Chegada" e "Revisao". Soma = 156mm (largura util do cartao).
    const campos = [
      ['Motorista', motor,                              'pessoa',   36],
      ['Telefone',  mObj && mObj.tel ? mObj.tel : '—',  'telefone', 36],
      ['Chegada',   chegada,                            'relogio',  24],
      ['Veículo',   rota.veiculo || '—',                'van',      36],
      ['Revisão',   'R' + rev,                          'revisao',  24]
    ];
    let cx = L + 25;
    campos.forEach((c, i) => {
      if (i > 0) {
        doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
        doc.line(cx - 3, y + 11, cx - 3, y + 20);
      }
      pdfRotuloValor(doc, c[0], c[1], cx, y + 15.5, c[2], c[3] - 8);
      cx += c[3];
    });
    y += 30;

    // ---- passageiros ----
    const sorted = [...rota.passageiros]
      .filter(p => p.status !== 'desligado')
      .sort((a, b) => {
        const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
        const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
        return ta.localeCompare(tb);
      });

    const statusLabel = { ativo: 'Ativo', ferias: 'Férias', afastado: 'Afastado' };
    const statusCor = {
      ativo:    { txt: PDF_COR.verde,    bg: PDF_COR.verdeClr },
      ferias:   { txt: PDF_COR.vermelho, bg: PDF_COR.vermeClr },
      afastado: { txt: PDF_COR.laranja,  bg: PDF_COR.laranjaC }
    };
    const fmtRetorno = (d) => {
      if (!d) return '';
      const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/);
      return m ? m[3] + '/' + m[2] + '/' + m[1] : d;
    };

    const meta = sorted.map(p => ({
      status: p.status,
      retorno: (p.status === 'ferias' || p.status === 'afastado') ? fmtRetorno(p.retorno) : ''
    }));

    // Dias com horario proprio neste turno. Vazio = tabela como sempre foi.
    const variantes = pdfDiasVariantes(rota.turno);
    const rows = sorted.map((p, i) => [i + 1,
        pdfHorarioNoDia(p.horario, rota.turno, dataPdf).txt
      ].concat(
        variantes.map(v => pdfHoraVariante(p.horario, rota.turno, v.chegada))
      ).concat([
        p.nome,
        p.telefone || '—',
        p.embarque || p.endereco || '—',
        p.bairro || '—',
        ''  // status desenhado à mão, como pílula
      ]));

    // A coluna diz o horario, nao QUAL sabado. Com alternancia isso
    // precisa estar escrito, senao o papel promete o que nao cumpre.
    const notasVar = variantes.filter(v => v.alternado && v.alt && v.alt.desde)
      .map(v => v.nome + ': esta linha opera a cada ' + (v.alt.semanas || 2) +
                ' semanas, a partir de ' + pdfDataBr(v.alt.desde));

    doc.autoTable({
      startY: y,
      head: [['#', variantes.length ? 'Dia útil' : 'Horário'].concat(
               variantes.map(v => v.nome)
             ).concat(['Passageiro', 'Telefone', 'Ponto de Embarque', 'Bairro', 'Status'])],
      body: rows,
      theme: 'plain',
      styles: {
        font: 'helvetica', fontSize: 8, cellPadding: { top: 2.6, bottom: 2.6, left: 2, right: 2 },
        textColor: PDF_COR.tinta, lineColor: PDF_COR.linha, lineWidth: 0,
        valign: 'middle', overflow: 'linebreak'
      },
      headStyles: {
        fillColor: PDF_COR.ambar, textColor: [255, 255, 255], fontStyle: 'bold',
        fontSize: 7.8, halign: 'left', cellPadding: { top: 3.6, bottom: 3.6, left: 2.4, right: 2.4 }
      },
      bodyStyles: { lineWidth: { bottom: 0.2 }, lineColor: PDF_COR.linha },
      // sem zebrado: o separador fino ja organiza a leitura
      alternateRowStyles: { fillColor: [255, 255, 255] },
      // 'avoid': se a linha nao cabe, ela inteira vai para a proxima pagina.
      // Sem isso o endereco parte no meio e a continuacao aparece orfa.
      rowPageBreak: 'avoid',
      // Somam 182mm (largura util). Telefone e Horario levam folga porque o
      // conteudo deles nao pode quebrar em duas linhas sem ficar ilegivel.
      columnStyles: (function () {
        // Larguras por POSICAO calculada, nao por indice fixo: cada
        // variante empurra as colunas seguintes.
        const nv = variantes.length;
        const st = {};
        // 182mm uteis (L=14, R=196). O autoTable precisa de folga interna,
        // entao o alvo e 172 — com 3+ variantes as colunas encolhem juntas
        // em vez de estourar a pagina.
        const UTIL = 172;
        const fixas = 9 + 16 + 24 + 21 + 20;          // #, horario, tel, bairro, status
        const largVar = nv ? Math.max(13, Math.min(16, Math.floor((UTIL - fixas - 48) / nv))) : 0;
        const sobra = UTIL - fixas - largVar * nv;    // divide entre nome e ponto
        const min = nv >= 4 ? 16 : 22;
        const nome = Math.max(min, Math.round(sobra * 0.48));
        const ponto = Math.max(min, sobra - nome);
        st[0] = { cellWidth: 9, halign: 'center', textColor: PDF_COR.suave };
        st[1] = { cellWidth: 16, halign: 'center', fontStyle: 'bold' };
        for (let k = 0; k < nv; k++)
          st[2 + k] = { cellWidth: largVar, halign: 'center', fontStyle: 'bold',
                        textColor: PDF_COR.destaque };
        st[2 + nv] = { cellWidth: nome };
        st[3 + nv] = { cellWidth: 24, fontSize: 7.6 };
        st[4 + nv] = { cellWidth: ponto };
        st[5 + nv] = { cellWidth: 21, fontSize: 7.8, textColor: PDF_COR.texto };
        st[6 + nv] = { cellWidth: 20, halign: 'center' };
        return st;
      })(),
      margin: { left: L, right: 210 - R, top: 24, bottom: 18 },
      didParseCell: function (d) {
        if (d.section === 'head' && d.column.index === 0) d.cell.styles.halign = 'center';
        if (d.section === 'head' && (d.column.index >= 1 && d.column.index <= 1 + variantes.length))
          d.cell.styles.halign = 'center';
        if (d.section === 'head' && d.column.index === 6 + variantes.length) d.cell.styles.halign = 'center';
      },
      didDrawCell: function (d) {
        if (d.section !== 'body' || d.column.index !== 6 + variantes.length) return;
        const info = meta[d.row.index];
        if (!info) return;
        const rot = statusLabel[info.status] || info.status;

        // "Ativo" é o estado normal: sai como texto neutro, sem pastilha.
        // Colorir 13 linhas iguais de verde não informa nada e ainda faz a
        // tabela parecer listrada. A cor fica reservada para a exceção.
        if (info.status === 'ativo') {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
          doc.setTextColor.apply(doc, PDF_COR.texto);
          doc.text(rot, d.cell.x + d.cell.width / 2, d.cell.y + d.cell.height / 2 + 1, { align: 'center' });
          return;
        }

        const cor = statusCor[info.status] || statusCor.ativo;
        const duas = !!info.retorno;
        const larguraPill = 19;
        const altura = duas ? 9 : 6;
        const px = d.cell.x + (d.cell.width - larguraPill) / 2;
        const py = d.cell.y + (d.cell.height - altura) / 2;
        doc.setFillColor.apply(doc, cor.bg);
        doc.setDrawColor.apply(doc, cor.txt);
        doc.setLineWidth(0.2);
        doc.roundedRect(px, py, larguraPill, altura, 1.6, 1.6, 'FD');
        doc.setTextColor.apply(doc, cor.txt);
        doc.setFont('helvetica', 'bold'); doc.setFontSize(7.6);
        doc.text(rot, px + larguraPill / 2, py + (duas ? 3.7 : 4), { align: 'center' });
        if (duas) {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(6);
          doc.text('Retorno ' + info.retorno, px + larguraPill / 2, py + 7.3, { align: 'center' });
        }
      },
      didDrawPage: function (d) {
        const primeira = d.pageNumber === 1;
        if (!primeira) pdfCabecalho(doc, ctx, false);
        pdfRodapePagina(doc, ctx);
      }
    });

    // ---- rodapé com totais ----
    // Se o cartão inteiro não couber, vira uma faixa de uma linha. Mandar uma
    // folha quase vazia só para carregar o total é feio num documento que o
    // cliente recebe — e o gestor imprime isso todo dia.
    const cap = getCapacidade(rota);
    const ativos = sorted.filter(p => p.status === 'ativo').length;
    let fy = doc.lastAutoTable.finalY + 7;
    const espaco = 280 - fy;

    if (espaco < 12) { doc.addPage(); pdfCabecalho(doc, ctx, false); pdfRodapePagina(doc, ctx); fy = 30; }

    if (280 - fy < 24) {
      // faixa compacta
      doc.setFillColor.apply(doc, PDF_COR.fundo);
      doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
      doc.roundedRect(L, fy, R - L, 10, 2, 2, 'FD');
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      doc.setTextColor.apply(doc, PDF_COR.tinta);
      doc.text(sorted.length + ' passageiros', L + 4, fy + 6.4);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
      doc.setTextColor.apply(doc, PDF_COR.suave);
      doc.text('· ' + ativos + ' ativos · ' + cap + ' vagas', L + 30, fy + 6.4);
      doc.setFontSize(7);
      doc.text('Garagem: ' + GARAGEM, L + 66, fy + 4.4);
      doc.text('Destino: ' + DESTINO, L + 66, fy + 8);
      pdfFinalizarPaginas(doc, ctx, R);
      const turnoNumC = rota.turno.replace('°', '');
      const dataFileC = hojeLocal(now) + '_' +
        now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }).replace(':', '');
      doc.save('L' + rota.linha + 'T' + turnoNumC + '_R' + rev + '_' + dataFileC + '.pdf');
      continue;
    }

    doc.setFillColor.apply(doc, PDF_COR.fundo);
    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.roundedRect(L, fy, R - L, 22, 3, 3, 'FD');

    pdfIcone(doc, 'grupo', L + 6, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Total de passageiros', L + 15, fy + 8);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(15);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(String(sorted.length), L + 15, fy + 16);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text(ativos + ' ativos · ' + cap + ' vagas', L + 26, fy + 15.4);

    doc.setDrawColor.apply(doc, PDF_COR.linha);
    doc.line(L + 58, fy + 4, L + 58, fy + 18);
    pdfIcone(doc, 'casa', L + 62, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Garagem', L + 71, fy + 8);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(doc.splitTextToSize(GARAGEM, 54), L + 71, fy + 13);

    doc.setDrawColor.apply(doc, PDF_COR.linha);
    doc.line(L + 128, fy + 4, L + 128, fy + 18);
    pdfIcone(doc, 'pino', L + 132, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Destino', L + 141, fy + 8);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(doc.splitTextToSize(DESTINO, 45), L + 141, fy + 13);

    pdfFinalizarPaginas(doc, ctx, R);

    const turnoNum = rota.turno.replace('°', '');
    const dataFile = hojeLocal(now) + '_' +
      now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }).replace(':', '');
    // Nota da alternancia, logo abaixo da tabela.
    if (notasVar.length) {
      const yN = (doc.lastAutoTable && doc.lastAutoTable.finalY || y) + 6;
      doc.setFontSize(7.5);
      doc.setTextColor.apply(doc, PDF_COR.suave || PDF_COR.tinta);
      notasVar.forEach((n, i) => doc.text(n, L, yN + i * 4));
      doc.setTextColor.apply(doc, PDF_COR.tinta);
    }

    const filename = 'L' + rota.linha + 'T' + turnoNum + '_R' + rev + '_' + dataFile + '.pdf';
    doc.save(filename);
  }
}

function renderOptResult(opt, chegadaHora) {
  const body = document.getElementById('optResultBody');
  const alertas = opt.novasParadas.filter(p => p.alerta);
  const sg = opt.saidaGaragem || 0;
  const absG = ((sg % 1440) + 1440) % 1440;
  const saidaH = Math.floor(absG / 60).toString().padStart(2,'0');
  const saidaM = (absG % 60).toString().padStart(2,'0');

  let html = '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--green)">' + opt.novasParadas.length + '</div><div class="report-stat-label">Paradas</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent)">' + opt.totalDuration + 'min</div><div class="report-stat-label">Duração total</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent2)">' + saidaH + ':' + saidaM + '</div><div class="report-stat-label">Saída Garagem</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:' + (alertas.length > 0 ? 'var(--red)' : 'var(--green)') + '">' + alertas.length + '</div><div class="report-stat-label">Alertas +60min</div></div>';
  html += '</div>';

  if (opt.passSemCoords && opt.passSemCoords.length > 0) {
    html += '<div style="background:rgba(245,158,11,0.08);border:1px solid rgba(245,158,11,0.3);border-radius:8px;padding:10px;margin-bottom:12px;font-size:12px;color:var(--accent)">Sem coordenadas: ' + opt.passSemCoords.map(p => p.nome.split(' ')[0]).join(', ') + '</div>';
  }

  html += '<div style="max-height:300px;overflow-y:auto">';
  opt.novasParadas.forEach((item, i) => {
    const alertHtml = item.alerta
      ? '<span class="alert-badge">' + item.minutosEmRota + 'min em rota</span>'
      : '<span style="font-size:10px;color:var(--muted)">' + item.minutosEmRota + 'min em rota</span>';
    html += '<div class="report-row">' +
      '<div class="report-time" style="font-weight:700;color:var(--accent);min-width:40px">' + (i+1) + '</div>' +
      '<div style="font-weight:600;font-size:13px;min-width:55px">' + item.horario + '</div>' +
      '<div style="flex:1"><div style="font-size:12px;font-weight:500">' + item.passageiro.nome + '</div>' + alertHtml + '</div>' +
    '</div>';
  });
  html += '</div>';
  body.innerHTML = html;
}

// ---- API KEY CONFIG ----
// Chave Firebase (NÃO é Maps Key) — usada para detectar cache corrompido
const FB_API_KEY = C.fb.apiKey;
let MAPS_API_KEY = '';

// Helper: escapar caracteres especiais para injeção segura em HTML
function esc(str) {
  return (str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ===== DATA LOCAL (fuso Brasilia UTC-3) =====
// Corrige o bug de toISOString() devolver UTC (que vira o dia seguinte apos 21h).
function hojeLocal(baseDate, offsetDias){
  var d = baseDate instanceof Date ? new Date(baseDate.getTime()) : new Date();
  if (offsetDias) d.setTime(d.getTime() + offsetDias*86400000);
  // desloca para -03:00 e formata em UTC para extrair a data local de Brasilia
  var br = new Date(d.getTime() - 3*3600000);
  return br.toISOString().slice(0,10);
}
function mesLocal(baseDate){
  var d = baseDate instanceof Date ? new Date(baseDate.getTime()) : new Date();
  var br = new Date(d.getTime() - 3*3600000);
  return br.toISOString().slice(0,7);
}

function _diaChat(m){ try{ var d = m && m.em ? new Date(m.em) : null; if(!d || isNaN(d)) return ''; return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }catch(e){ return ''; } }
function _fmtDiaChat(m){ try{ var d = new Date(m.em); var hoje=new Date(); var ymd=function(x){return x.getFullYear()+'-'+x.getMonth()+'-'+x.getDate();}; var ont=new Date(hoje); ont.setDate(hoje.getDate()-1); if(ymd(d)===ymd(hoje)) return 'Hoje'; if(ymd(d)===ymd(ont)) return 'Ontem'; return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); }catch(e){ return ''; } }
function _sepDataChat(m, anterior){ var dAtual=_diaChat(m); if(!dAtual) return ''; var dAnt = anterior ? _diaChat(anterior) : ''; if(dAtual===dAnt) return ''; var lbl=_fmtDiaChat(m); if(!lbl) return ''; return '<div style="align-self:center;margin:8px auto;padding:3px 12px;background:rgba(128,128,128,0.18);border-radius:12px;font-size:11px;font-weight:600;color:var(--muted);text-align:center">'+lbl+'</div>'; }

function waLink(tel) { if (!tel) return ''; var n = tel.replace(/\D/g,''); return '<a href="https://wa.me/55' + n + '" target="_blank" style="color:#25D366;text-decoration:none;font-weight:600">' + tel + '</a>'; }
// ---------------------------------------------------------------------------
// CHAVE DO GOOGLE MAPS
// Infraestrutura da temvia, nao configuracao da operacao. A fonte e a casca
// (arquivo do repositorio, so a temvia edita). Nao ha editor em tela nenhuma.
//
// TRANSICAO: enquanto houver casca sem `mapsKey`, o Firestore e o localStorage
// continuam valendo como reserva de LEITURA, com aviso no console. Remover as
// duas reservas assim que todas as operacoes estiverem publicadas.
// ---------------------------------------------------------------------------
function chaveDaCasca() {
  try {
    var k = window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.mapsKey;
    return (typeof k === 'string' && k.indexOf('AIza') === 0) ? k : '';
  } catch (e) { return ''; }
}

function getApiKey() {
  if (MAPS_API_KEY) return MAPS_API_KEY;

  var daCasca = chaveDaCasca();
  if (daCasca) { MAPS_API_KEY = daCasca; return MAPS_API_KEY; }

  // --- reserva temporaria ---
  var cache = '';
  try { cache = localStorage.getItem('redentor_maps_key') || ''; } catch (e) {}
  if (cache && cache !== FB_API_KEY) {
    console.warn('[temvia] Chave do Maps veio do cache local. ' +
                 'Publique mapsKey na casca desta operacao.');
    MAPS_API_KEY = cache;
  } else if (cache === FB_API_KEY) {
    // Cache corrompido de versoes antigas guardava a chave do Firebase aqui.
    try { localStorage.removeItem('redentor_maps_key'); } catch (e) {}
  }
  return MAPS_API_KEY;
}

// Busca a Maps API Key do Firebase (salva pelo gestor via Config)
async function fetchMapsKeyFromFirebase() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) return '';
    const { getDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const configRef = doc(fbDb, CLIENTE_ID, 'config');
    const snap = await getDoc(configRef);
    if (snap.exists() && snap.data().mapsApiKey) {
      const key = snap.data().mapsApiKey;
      localStorage.setItem('redentor_maps_key', key); // cache local
      MAPS_API_KEY = key;
      return key;
    }
  } catch(e) {
    console.warn('Erro ao buscar Maps Key do Firebase:', e.message);
  }
  return '';
}

// ---- MOTORISTA VIEW (from main system) ----

function motoFilterLinhas() {
  const motoNome = document.getElementById('motoSelectMotorista').value;
  const sel = document.getElementById('motoSelectLinha');
  sel.innerHTML = '<option value="">— Selecione uma linha —</option>';
  DATA.forEach(rota => {
    if (motoNome && rota.motorista !== motoNome && rota.motoristaSaida !== motoNome) return;
    const ativos = rota.passageiros.filter(p => p.status === 'ativo').length;
    if (ativos === 0) return;
    const chegada = {'1°':'05:45','2°':'14:45','3°':'20:55'}[rota.turno] || '';
    const opt = document.createElement('option');
    opt.value = rota.id;
    opt.textContent = 'Linha ' + rota.linha + ' · ' + rota.turno + ' Turno · ' + ativos + ' pass. · chegada ' + chegada;
    sel.appendChild(opt);
  });
  document.getElementById('motoRotaContent').innerHTML = '';
}

function motoLoadRota() {
  const rotaId = document.getElementById('motoSelectLinha').value;
  const content = document.getElementById('motoRotaContent');
  if (!rotaId) { content.innerHTML = ''; return; }
  const rota = DATA.find(r => r.id === rotaId);
  if (!rota) return;
  const chegada = {'1°':'05:45','2°':'14:45','3°':'20:55'}[rota.turno] || '';
  const mObj = MOTORISTAS.find(m => m.nome === rota.motorista);
  const mObjS = rota.motoristaSaida ? MOTORISTAS.find(m => m.nome === rota.motoristaSaida) : null;
  const sorted = rota.passageiros
    .filter(p => p.status === 'ativo')
    .sort((a,b) => (a.horario||'99:99').localeCompare(b.horario||'99:99'));

  function buildMapsUrlLocal(stops) {
    const garAddr = encodeURIComponent('R. Sebastiana Rosa Luposeli, 59, Sorocaba SP');
    const empAddr = encodeURIComponent('Av. Jerome Case, 2600, Eden, Sorocaba SP');
    if (stops.length === 0) return 'https://www.google.com/maps/dir/?api=1&origin=' + garAddr + '&destination=' + empAddr + '&travelmode=driving';
    const waypoints = stops.slice(0,8).map(p => p.lat && p.lng ? p.lat+','+p.lng : encodeURIComponent((p.embarque||p.endereco||'')+', '+(p.cidade||'Sorocaba')+' SP'));
    return 'https://www.google.com/maps/dir/?api=1&origin=' + garAddr + '&destination=' + empAddr + '&waypoints=' + waypoints.join('%7C') + '&travelmode=driving';
  }

  function buildWazeUrlLocal(p) {
    if (p && p.lat && p.lng) return 'https://waze.com/ul?ll=' + p.lat + ',' + p.lng + '&navigate=yes&zoom=17';
    const q = encodeURIComponent(((p&&(p.embarque||p.endereco))||'') + ', ' + ((p&&p.cidade)||'Sorocaba') + ' SP');
    return 'https://waze.com/ul?q=' + q + '&navigate=yes';
  }

  const mapsUrl = buildMapsUrlLocal(sorted);
  const wazeUrl = sorted.length > 0 ? buildWazeUrlLocal(sorted[0]) : '#';

  let html = '<div class="chips">';
  html += '<span class="chip chip-turno">' + rota.turno + ' Turno</span>';
  html += '<span class="chip chip-pass">' + sorted.length + ' passageiros</span>';
  html += '<span class="chip chip-vei">' + rota.veiculo + '</span></div>';

  if (mObj) {
    html += '<div class="moto-info-card"><div class="moto-info-title">Motorista</div>';
    html += '<div class="moto-name">' + mObj.nome + '</div>';
    if (mObj.tel) html += '<div class="moto-tel">' + mObj.tel + '</div>';
    if (mObjS) html += '<div style="margin-top:8px;font-size:12px;color:var(--muted)">Saída: <strong>' + mObjS.nome + '</strong>' + (mObjS.tel ? ' · ' + mObjS.tel : '') + '</div>';
    html += '</div>';
  }

  html += '<div class="nav-btns-row">';
  html += '<a href="' + mapsUrl + '" target="_blank" class="nav-maps-btn"><span style="font-size:18px"></span> Google Maps</a>';
  html += '<a href="' + wazeUrl + '" target="_blank" class="nav-waze-btn">Waze</a>';
  html += '</div>';

  html += '<div class="moto-info-card">';
  html += '<div class="moto-info-title" style="color:var(--green)">Garagem Redentor</div>';
  html += '<div style="font-size:12px;color:var(--muted)">R. Sebastiana Rosa Luposeli, 59 — Júlio de Mesquita Filho</div></div>';

  html += '<div class="moto-info-card"><div class="moto-info-title">Paradas</div>';
  sorted.forEach((p, i) => {
    const addr = p.embarque || p.endereco || '—';
    const mapsStop = p.lat && p.lng ? 'https://www.google.com/maps/search/?api=1&query=' + p.lat + ',' + p.lng : 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(addr + ', ' + (p.cidade||'Sorocaba') + ' SP');
    const wazeStop = buildWazeUrlLocal(p);
    html += '<div class="moto-stop"><div class="moto-stop-num">' + (i+1) + '</div>';
    html += '<div style="flex:1"><div style="display:flex;gap:8px;align-items:center">';
    html += '<div class="moto-stop-time">' + (p.horario||'--:--') + '</div>';
    html += '<div><div class="moto-stop-name">' + p.nome.split(' ').slice(0,2).join(' ') + '</div>';
    if (p.telefone) html += '<div class="moto-stop-tel">' + p.telefone + '</div>';
    html += '</div></div><div class="moto-stop-addr">' + addr + '</div>';
    html += '<div class="stop-nav-row"><a href="' + mapsStop + '" target="_blank" class="stop-nav-maps">Google Maps</a>';
    html += '<a href="' + wazeStop + '" target="_blank" class="stop-nav-waze">Waze</a></div>';
    html += '</div></div>';
  });
  html += '</div>';

  html += '<div class="moto-dest"><div class="moto-dest-label">Destino Final</div>';
  html += '<div class="moto-dest-time">' + chegada + '</div>';
  html += '<div class="dest-addr" style="font-size:12px;color:var(--muted);margin-top:4px">Av. Jerome Case, 2600 — Éden, Sorocaba-SP</div></div>';

  content.innerHTML = html;
}

// ---- ROUTE OPTIMIZATION ----
const GARAGEM_COORDS = { lat: -23.514606111185454, lng: -47.51671157145018 };
const EMPRESA_COORDS = { lat: -23.44293641550631, lng: -47.389652010783614 };
const MAX_ROTA_MINUTOS = 60;
let otimizarRotaId = null;
let pendingOptimization = null;
let lastDirectionsResult = null;
let optMap = null;
let optDirectionsRenderer = null;

function setOptStatus(msg, type) {
  const el = document.getElementById('optStatus');
  if (!el) return;
  el.textContent = msg;
  el.className = 'opt-status ' + (type || '');
}

async function ensureMapsLoaded() {
  const key = getApiKey();
  if (!key) throw new Error('API Key não configurada. Clique em Config.');
  if (window.google && window.google.maps && window.google.maps.Map) return;
  setOptStatus('Carregando Google Maps API...', 'running');
  try {
    await loadGoogleMaps(key);
    await new Promise(r => setTimeout(r, 800));
    if (!window.google || !window.google.maps) {
      throw new Error('Google Maps não carregou. Verifique: (1) API Key correta, (2) APIs ativadas no Google Cloud, (3) Faturamento ativado.');
    }
  } catch(e) {
    throw new Error('Erro ao carregar Maps: ' + e.message);
  }
}

function getPassengerAddress(p) {
  return p.embarque && p.embarque.trim() ? p.embarque.trim() : (p.endereco || '').trim();
}

async function geocodeAddress(geocoder, address, cidade) {
  return new Promise((resolve) => {
    const cidadeStr = cidade && cidade.trim() ? cidade.trim() : 'Sorocaba';
    const cleanAddr = address.replace(/\s+/g, ' ').trim();
    const fullAddr = cleanAddr + ', ' + cidadeStr + ', SP, Brasil';
    const timer = setTimeout(() => { resolve(null); }, 10000);
    geocoder.geocode({ address: fullAddr, region: 'BR' }, (results, status) => {
      clearTimeout(timer);
      if (status === 'OK' && results[0]) {
        resolve({ lat: results[0].geometry.location.lat(), lng: results[0].geometry.location.lng() });
      } else {
        resolve(null);
      }
    });
  });
}

async function getCoords(geocoder, p) {
  if (p.lat && p.lng && Math.abs(p.lat) > 1 && Math.abs(p.lng) > 1) {
    return { lat: p.lat, lng: p.lng };
  }
  const addr = getPassengerAddress(p);
  return await geocodeAddress(geocoder, addr, p.cidade);
}

function openOtimizar(rotaId) {
  // O cliente acompanha e solicita; quem reorganiza a rota e o gestor
  // da transportadora.
  alert('A otimização de rota é feita pelo gestor da transportadora.');
  return;
  const key = getApiKey();
  if (!key) { alert('Configure sua Google Maps API Key primeiro.\nClique em Config no cabeçalho.'); return; }
  otimizarRotaId = rotaId;
  const rota = DATA.find(r => r.id === rotaId);
  const chegada = { '1°': '05:45', '2°': '14:45', '3°': '20:55' }[rota.turno] || '';
  document.getElementById('otimizarTitle').textContent = 'Otimizar — Linha ' + rota.linha + ' · ' + rota.turno + ' Turno';
  setOptStatus('Aguardando...', '');
  document.getElementById('optResultSection').style.display = 'none';
  document.getElementById('optMapSection').style.display = 'none';
  // btnAplicar removido (cliente somente leitura)
  document.getElementById('btnVerMapa').style.display = 'none';
  document.getElementById('btnVerMapa').textContent = 'Ver Mapa';
  pendingOptimization = null;
  document.getElementById('modalOtimizar').classList.add('open');
}

async function otimizarRotaAtual() {
  // O cliente acompanha e solicita; quem reorganiza a rota e o gestor.
  alert('A otimização de rota é feita pelo gestor da transportadora.');
  return;
  const btn = document.getElementById('btnOtimizarRota');
  btn.disabled = true;
  setOptStatus('Carregando Google Maps...', 'running');
  try {
    await ensureMapsLoaded();
    const rota = DATA.find(r => r.id === otimizarRotaId);
    const passAtivos = rota.passageiros.filter(p => p.status === 'ativo' && (p.endereco || p.embarque));
    if (passAtivos.length === 0) { setOptStatus('Nenhum passageiro ativo com endereço.', 'error'); btn.disabled = false; return; }

    setOptStatus('Buscando coordenadas...', 'running');
    const geocoder = new google.maps.Geocoder();
    const coordsMap = {};
    for (let i = 0; i < passAtivos.length; i++) {
      const p = passAtivos[i];
      setOptStatus('' + (i+1) + '/' + passAtivos.length + ': ' + p.nome.split(' ')[0] + '...', 'running');
      coordsMap[p.nome] = await getCoords(geocoder, p);
      await new Promise(r => setTimeout(r, 150));
    }

    const passComCoords = passAtivos.filter(p => coordsMap[p.nome]);
    const passSemCoords = passAtivos.filter(p => !coordsMap[p.nome]);
    if (passComCoords.length === 0) { setOptStatus('Nenhum endereço pôde ser geocodificado.', 'error'); btn.disabled = false; return; }

    // Use Distance Matrix to sort by distance to empresa (furthest first)
    setOptStatus('Calculando distâncias à empresa...', 'running');
    const distanceService = new google.maps.DistanceMatrixService();
    const origins = passComCoords.map(p => new google.maps.LatLng(coordsMap[p.nome].lat, coordsMap[p.nome].lng));

    const matrixResult = await new Promise((resolve, reject) => {
      distanceService.getDistanceMatrix({
        origins, destinations: [new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng)],
        travelMode: google.maps.TravelMode.DRIVING,
      }, (res, status) => { if (status === 'OK') resolve(res); else reject(new Error('Distance Matrix: ' + status)); });
    });

    const distToEmpresa = passComCoords.map((p, i) => {
      const el = matrixResult.rows[i].elements[0];
      return el.status === 'OK' ? el.distance.value : 0;
    });

    const indexed = passComCoords.map((p, i) => ({ p, dist: distToEmpresa[i] }));
    indexed.sort((a, b) => b.dist - a.dist);
    const ordered = indexed.map(x => x.p);

    setOptStatus('Calculando tempos reais...', 'running');
    const directionsService = new google.maps.DirectionsService();
    const chegadaHora = { '1°': '05:45', '2°': '14:45', '3°': '20:55' }[rota.turno] || '05:45';
    const [hh, mm] = chegadaHora.split(':').map(Number);
    const chegadaMinutes = hh * 60 + mm;

    const waypoints = ordered.map(p => ({ location: new google.maps.LatLng(coordsMap[p.nome].lat, coordsMap[p.nome].lng), stopover: true }));
    const result = await new Promise((resolve, reject) => {
      directionsService.route({
        origin: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
        destination: new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng),
        waypoints, optimizeWaypoints: false,
        travelMode: google.maps.TravelMode.DRIVING,
      }, (res, status) => { if (status === 'OK') resolve(res); else reject(new Error('Directions API: ' + status)); });
    });

    const legs = result.routes[0].legs;
    const n = ordered.length;
    let totalSeconds = 0;
    legs.forEach(leg => { totalSeconds += leg.duration.value; });

    const boardingMinutes = new Array(n);
    let timeBack = chegadaMinutes;
    for (let i = n - 1; i >= 0; i--) { timeBack -= Math.round(legs[i+1].duration.value / 60); boardingMinutes[i] = timeBack; }
    const saidaGaragem = boardingMinutes[0] - Math.round(legs[0].duration.value / 60);

    const novasParadas = [];
    for (let i = 0; i < n; i++) {
      const p = ordered[i];
      const absMin = ((boardingMinutes[i] % 1440) + 1440) % 1440;
      const h = Math.floor(absMin / 60), m = absMin % 60;
      const horario = h.toString().padStart(2,'0') + ':' + m.toString().padStart(2,'0');
      const minutosEmRota = chegadaMinutes - boardingMinutes[i];
      novasParadas.push({ passageiro: p, horario, minutosEmRota, alerta: minutosEmRota > MAX_ROTA_MINUTOS, distanciaLeg: legs[i+1] ? legs[i+1].distance.text : '—' });
    }

    pendingOptimization = { rotaId: otimizarRotaId, novasParadas, passSemCoords, totalDuration: Math.round(totalSeconds/60), saidaGaragem, coordsMap };
    lastDirectionsResult = result;
    optMap = null; optDirectionsRenderer = null;

    renderOptResult(pendingOptimization, chegadaHora);
    setOptStatus('Otimização concluída! Revise e clique em "Aplicar alterações".', 'success');
    // btnAplicar removido (cliente somente leitura)
    document.getElementById('btnVerMapa').style.display = 'inline-block';
    document.getElementById('optResultSection').style.display = 'block';
  } catch(e) { setOptStatus('Erro: ' + e.message, 'error'); console.error(e); }
  btn.disabled = false;
}

async function recalcularApenasHorarios() {
  const rota = DATA.find(r => r.id === otimizarRotaId);
  const btn = document.querySelector('#modalOtimizar .opt-btn-secondary');
  if (btn) btn.disabled = true;
  setOptStatus('Carregando Google Maps...', 'running');
  try {
    await ensureMapsLoaded();
    const passAtivos = rota.passageiros.filter(p => p.status === 'ativo' && (p.endereco || p.embarque));
    const sorted = [...passAtivos].sort((a,b) => (a.horario||'99:99').localeCompare(b.horario||'99:99'));
    const geocoder = new google.maps.Geocoder();
    const coordsMap = {};
    for (let i = 0; i < sorted.length; i++) {
      const p = sorted[i];
      setOptStatus('' + (i+1) + '/' + sorted.length + ' ' + p.nome.split(' ')[0] + '...', 'running');
      coordsMap[p.nome] = await getCoords(geocoder, p);
      await new Promise(r => setTimeout(r, 150));
    }
    const passComCoords = sorted.filter(p => coordsMap[p.nome]);
    const passSemCoords = sorted.filter(p => !coordsMap[p.nome]);
    setOptStatus('Recalculando horários na ordem atual...', 'running');
    const directionsService = new google.maps.DirectionsService();
    const chegadaHora = { '1°': '05:45', '2°': '14:45', '3°': '20:55' }[rota.turno] || '05:45';
    const [hh, mm] = chegadaHora.split(':').map(Number);
    const chegadaMinutes = hh * 60 + mm;
    const waypoints = passComCoords.map(p => ({ location: new google.maps.LatLng(coordsMap[p.nome].lat, coordsMap[p.nome].lng), stopover: true }));
    const result = await new Promise((resolve, reject) => {
      directionsService.route({
        origin: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
        destination: new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng),
        waypoints, optimizeWaypoints: false,
        travelMode: google.maps.TravelMode.DRIVING,
      }, (res, status) => { if (status === 'OK') resolve(res); else reject(new Error('Directions: ' + status)); });
    });
    const legs = result.routes[0].legs;
    const n = passComCoords.length;
    let totalSeconds = 0;
    legs.forEach(leg => { totalSeconds += leg.duration.value; });
    const boardingMinutes = new Array(n);
    let timeBack = chegadaMinutes;
    for (let i = n-1; i >= 0; i--) { timeBack -= Math.round(legs[i+1].duration.value/60); boardingMinutes[i] = timeBack; }
    const saidaGaragem = boardingMinutes[0] - Math.round(legs[0].duration.value/60);
    const novasParadas = [];
    for (let i = 0; i < n; i++) {
      const p = passComCoords[i];
      const absMin = ((boardingMinutes[i] % 1440) + 1440) % 1440;
      const h = Math.floor(absMin/60), m = absMin % 60;
      const horario = h.toString().padStart(2,'0') + ':' + m.toString().padStart(2,'0');
      novasParadas.push({ passageiro: p, horario, minutosEmRota: chegadaMinutes - boardingMinutes[i], alerta: (chegadaMinutes - boardingMinutes[i]) > MAX_ROTA_MINUTOS });
    }
    pendingOptimization = { rotaId: otimizarRotaId, novasParadas, passSemCoords, totalDuration: Math.round(totalSeconds/60), saidaGaragem, coordsMap, keepOrder: true };
    lastDirectionsResult = result;
    optMap = null; optDirectionsRenderer = null;
    renderOptResult(pendingOptimization, chegadaHora);
    setOptStatus('Horários recalculados! Revise e aplique.', 'success');
    // btnAplicar removido (cliente somente leitura)
    document.getElementById('btnVerMapa').style.display = 'inline-block';
    document.getElementById('optMapSection').style.display = 'none';
    document.getElementById('btnVerMapa').textContent = 'Ver Mapa';
    document.getElementById('optResultSection').style.display = 'block';
  } catch(e) { setOptStatus('Erro: ' + e.message, 'error'); }
  if (btn) btn.disabled = false;
}

