function tvToggleSidebar() {
  const sh = document.getElementById('tvShell');
  if (!sh) return;
  sh.classList.toggle('tv-collapsed');
  try { localStorage.setItem('cli_sidebar', sh.classList.contains('tv-collapsed') ? '1' : '0'); } catch (e) {}
}

function cliIrParaLinhas() {
  document.querySelectorAll('.modal-overlay.open').forEach(m => m.classList.remove('open'));
  cliMarcarNav('Linhas e Rotas');
}

// A trilha e o item ativo dizem onde a pessoa esta — sem isso o menu
// seria so enfeite.
function cliMarcarNav(rotulo) {
  document.querySelectorAll('.tv-nav-item').forEach(b =>
    b.classList.toggle('tv-on', b.getAttribute('title') === rotulo));
  const c = document.getElementById('cliCrumb');
  if (c) c.textContent = rotulo;
}

function cliIdentificar() {
  // Cadastro primeiro; o apelido da casca so enquanto ele nao chegou.
  const cfg = (typeof EMPRESA_CONFIG !== 'undefined' && EMPRESA_CONFIG) || {};
  const nome = String(cfg.nome || '').trim() ||
    (window.CLIENTE_CONFIG && (window.CLIENTE_CONFIG.marca || '')) || 'Empresa';
  const el = document.getElementById('tvUserNome');
  if (el) el.textContent = nome;
  const av = document.getElementById('tvAvatar');
  if (av) av.textContent = nome.trim().slice(0, 2).toUpperCase();
  const ctx = document.getElementById('tvContextoConta');
  if (ctx) ctx.textContent = nome;
  const op = document.getElementById('tvOperacaoAtendida');
  const atendida = String(cfg.operacaoNome || '').trim();
  if (op) {
    const amb = window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.ambienteTeste;
    const txt = [amb ? 'AMBIENTE DE TESTE' : '', atendida ? 'Atendendo ' + atendida : '']
      .filter(Boolean).join(' \u00b7 ');
    op.style.display = txt ? '' : 'none';
    op.textContent = txt;
  }
  try {
    if (localStorage.getItem('cli_sidebar') === '1')
      document.getElementById('tvShell').classList.add('tv-collapsed');
  } catch (e) {}
}

// Monta assim que o bloco carrega — mesma funcao, mesmo escopo.
// O DOM ja existe: o body foi preenchido no topo do arquivo.
try { cliMontarCasca(); } catch (e) { console.warn('casca do cliente:', e && e.message); }

function openPainel() {
  try { cliMarcarNav('Painel Geral'); } catch (e) {}
  const body = document.getElementById('painelBody');

  const totalAtivos = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'ativo').length, 0);
  const totalFerias = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'ferias').length, 0);
  const totalAfastado = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'afastado').length, 0);
  const ordemTurnoP = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const turnosPresentesP = [...new Set(DATA.filter(r => r.passageiros && r.passageiros.length).map(r => r.turno))]
    .sort((a,b) => (ordemTurnoP[a]||9) - (ordemTurnoP[b]||9));
  const contagemTurnoP = {};
  turnosPresentesP.forEach(t => { contagemTurnoP[t] = DATA.reduce((s, r) => r.turno === t ? s + r.passageiros.filter(p=>p.status==='ativo').length : s, 0); });

  const linhasUnicas = [...new Set(DATA.map(r => r.linha))].sort((a,b)=>a-b);

  let html = '<div class="report-summary" style="margin-bottom:20px">' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--green)">' + totalAtivos + '</div><div class="report-stat-label">Ativos</div></div>' +
    turnosPresentesP.map(t => '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent)">' + contagemTurnoP[t] + '</div><div class="report-stat-label">' + (t==='ADM'?'ADM':(t+' Turno')) + '</div></div>').join('') +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent2)">' + totalFerias + '</div><div class="report-stat-label">Férias</div></div>' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--red)">' + totalAfastado + '</div><div class="report-stat-label">Afastados</div></div>' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--muted)">' + DESLIGADOS.length + '</div><div class="report-stat-label">Desligados</div></div>' +
  '</div>';

  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px">';

  linhasUnicas.forEach(linha => {
    const rotas = DATA.filter(r => r.linha === linha);
    const veiculo = rotas[0]?.veiculo || 'Van';
    const cap = veiculo === 'Carro' ? 4 : 15;
    const motorE = rotas[0]?.motorista || 'A definir';
    const mObj = MOTORISTAS.find(m => m.nome === motorE);

    html += '<div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px 16px">';
    html += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">';
    html += '<div class="line-badge ' + lc(linha) + '" style="width:34px;height:34px;font-size:15px">' + linha + '</div>';
    html += '<div><div style="font-family:Barlow,sans-serif;font-weight:700;font-size:14px">Linha ' + linha + ' · ' + veiculo + '</div>';
    html += '<div style="font-size:11px;color:var(--muted)">' + motorE + (mObj && mObj.tel ? ' · ' + mObj.tel : '') + '</div></div></div>';

    rotas.forEach(rota => {
      const ocupantes = rota.passageiros.filter(p => p.status === 'ativo' || p.status === 'ferias' || p.status === 'afastado').length;
      const vagas = cap - ocupantes;
      const pct = Math.round((ocupantes / cap) * 100);
      const barColor = pct >= 100 ? 'var(--red)' : pct >= 80 ? 'var(--accent)' : 'var(--green)';

      html += '<div style="margin-bottom:8px">';
      html += '<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px">';
      html += '<span style="color:var(--muted)">' + rota.turno + ' Turno</span>';
      html += '<span style="font-weight:600">' + ocupantes + '/' + cap;
      html += (vagas > 0 ? ' <span style="color:var(--green);font-size:10px">(' + vagas + ' vagas)</span>' : ' <span style="color:var(--red);font-size:10px">LOTADO</span>') + '</span></div>';
      html += '<div style="background:var(--surface2);border-radius:4px;height:6px;overflow:hidden">';
      html += '<div style="width:' + Math.min(pct,100) + '%;height:100%;background:' + barColor + ';border-radius:4px;transition:width 0.3s"></div></div></div>';
    });

    html += '</div>';
  });

  html += '</div>';
  body.innerHTML = html;
  document.getElementById('modalPainel').classList.add('open');
}

