// ---- MAPA GERAL ----
const MG_COLORS = {
  1: '#f59e0b', // amber
  2: '#3b82f6', // blue
  3: '#10b981', // green
  4: '#ef4444', // red
  5: '#8b5cf6', // purple
  6: '#f97316', // orange
  7: '#06b6d4', // cyan
};

let mgTurno = '1°';
let mgLinhasSel = new Set([1,2,3,4,5,6,7]);
let mgMap = null;
let mgMarkers = [];
let mgPolylines = [];
let mgDirectionsRenderers = [];
let mgInfoWindow = null;

async function openMapaGeral(rotaExtraIdx) {
  try { cliMarcarNav('Mapa Geral'); } catch (e) {}
  // 1. Tentar cache local
  let key = getApiKey();

  // 2. Tentar Firebase
  if (!key) key = await fetchMapsKeyFromFirebase();

  // 3. Sem chave configurada: a chave do Maps e infraestrutura da temvia,
  //    nao configuracao da operacao. A tela explica em vez de pedir.
  if (!key) {
    document.getElementById('modalMapaGeral').classList.add('open');
    renderMapaTurnoBar();
    document.getElementById('mapaGeralDiv').innerHTML =
      '<div style="display:flex;flex-direction:column;align-items:center;' +
      'justify-content:center;height:100%;gap:12px;padding:28px;text-align:center">' +
      '<div style="font-weight:700;font-size:15px;color:var(--text)">Mapa indispon\u00edvel</div>' +
      '<div style="font-size:12.5px;color:var(--muted);max-width:340px;line-height:1.5">' +
      'A chave do Google Maps desta opera\u00e7\u00e3o n\u00e3o est\u00e1 configurada. ' +
      'Ela faz parte da infraestrutura da plataforma \u2014 fale com a temvia.</div></div>';
    return;
  }

  _iniciarMapa(rotaExtraIdx);
}

function _iniciarMapa(rotaExtraIdx) {
  document.getElementById('modalMapaGeral').classList.add('open');
  renderMapaTurnoBar();
  buildLinhasCheck();
  ensureMapsLoaded().then(() => {
    initMapaGeral();
    setTimeout(() => {
      if (mgMap) google.maps.event.trigger(mgMap, 'resize');
      renderMapaGeral(rotaExtraIdx);
    }, 150);
  }).catch(e => alert('Erro ao carregar Maps: ' + e.message));
}

function initMapaGeral() {
  if (mgMap) return;
  mgInfoWindow = new google.maps.InfoWindow();
  mgMap = new google.maps.Map(document.getElementById('mapaGeralDiv'), {
    zoom: 11,
    center: new google.maps.LatLng(-23.5, -47.46),
    mapTypeId: 'roadmap',
    styles: [
      { elementType: 'geometry', stylers: [{ color: '#1c2330' }] },
      { elementType: 'labels.text.fill', stylers: [{ color: '#8b949e' }] },
      { elementType: 'labels.text.stroke', stylers: [{ color: '#0d1117' }] },
      { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#2d3748' }] },
      { featureType: 'road.highway', elementType: 'geometry', stylers: [{ color: '#3b4a6b' }] },
      { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#0d1117' }] },
      { featureType: 'landscape', elementType: 'geometry', stylers: [{ color: '#161b22' }] },
      { featureType: 'poi', visibility: 'off' },
      { featureType: 'transit', visibility: 'off' },
    ],
    fullscreenControl: true,
    mapTypeControl: false,
    streetViewControl: false,
  });
}

function buildLinhasCheck() {
  const container = document.getElementById('mgLinhasCheck');
  const linhas = [...new Set(DATA.map(r => r.linha))].sort((a,b) => a-b);
  container.innerHTML = '';
  linhas.forEach(l => {
    const color = MG_COLORS[l] || '#fff';
    const btn = document.createElement('button');
    btn.id = 'mgL' + l;
    btn.style.cssText = `background:${mgLinhasSel.has(l) ? color : 'transparent'};color:${mgLinhasSel.has(l) ? '#000' : color};border:2px solid ${color};border-radius:6px;padding:3px 10px;font-size:12px;font-weight:700;cursor:pointer;transition:all 0.15s`;
    btn.textContent = 'L' + l;
    btn.onclick = () => toggleLinha(l, btn, color);
    container.appendChild(btn);
  });
}

function toggleLinha(l, btn, color) {
  if (mgLinhasSel.has(l)) {
    mgLinhasSel.delete(l);
    btn.style.background = 'transparent';
    btn.style.color = color;
  } else {
    mgLinhasSel.add(l);
    btn.style.background = color;
    btn.style.color = '#000';
  }
  renderMapaGeral();
}

function mgSelectAll() {
  DATA.forEach(r => mgLinhasSel.add(r.linha));
  buildLinhasCheck();
  renderMapaGeral();
}

function mgSelectNone() {
  mgLinhasSel.clear();
  buildLinhasCheck();
  renderMapaGeral();
}

function renderMapaTurnoBar() {
  const bar = document.getElementById('mgTurnoBar');
  if (!bar) return;
  const ordem = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const presentes = [...new Set(DATA.filter(r => r.passageiros && r.passageiros.length).map(r => r.turno))]
    .sort((a,b) => (ordem[a]||9) - (ordem[b]||9));
  if (!presentes.includes(mgTurno)) mgTurno = presentes[0] || '1°';
  let html = '<span style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px">Turno:</span>';
  presentes.forEach(t => {
    const label = (t === 'ADM') ? 'ADM' : (t + ' Turno');
    html += '<button class="turno-btn' + (mgTurno===t?' active':'') + '" onclick="setMapaTurno(\'' + t + '\', this)">' + label + '</button>';
  });
  bar.innerHTML = html;
}

function setMapaTurno(t, btn) {
  mgTurno = t;
  document.querySelectorAll('[id^="mgTurno"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderMapaGeral();
}

function clearMapaGeral() {
  mgMarkers.forEach(m => m.setMap(null)); mgMarkers = [];
  mgPolylines.forEach(p => p.setMap(null)); mgPolylines = [];
  mgDirectionsRenderers.forEach(r => r.setMap(null)); mgDirectionsRenderers = [];
}

async function renderMapaGeral(rotaExtraIdx) {
  if (!mgMap) return;
  clearMapaGeral();

  const showRoutes = document.getElementById('mgShowRoutes').checked;
  const rotas = DATA.filter(r => r.turno === mgTurno && mgLinhasSel.has(r.linha));
  const legend = document.getElementById('mgLegend');
  legend.innerHTML = '';
  const bounds = new google.maps.LatLngBounds();
  let hasPoints = false;

  // Garagem marker
  const garPos = new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng);
  const garMarker = new google.maps.Marker({
    position: garPos, map: mgMap,
    title: 'Garagem Redentor',
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#10b981', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
    zIndex: 100
  });
  garMarker.addListener('click', () => {
    mgInfoWindow.setContent('<div style="color:#000;font-size:13px;font-weight:700">Garagem Redentor</div><div style="font-size:11px">R. Sebastiana Rosa Luposeli, 59</div>');
    mgInfoWindow.open(mgMap, garMarker);
  });
  mgMarkers.push(garMarker);
  bounds.extend(garPos);

  // Empresa marker
  const empPos = new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng);
  const empMarker = new google.maps.Marker({
    position: empPos, map: mgMap,
    title: 'Empresa',
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#3b82f6', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
    zIndex: 100
  });
  empMarker.addListener('click', () => {
    mgInfoWindow.setContent('<div style="color:#000;font-size:13px;font-weight:700">Huawei — Empresa</div><div style="font-size:11px">Av. Jerome Case, 2600 — Éden</div>');
    mgInfoWindow.open(mgMap, empMarker);
  });
  mgMarkers.push(empMarker);
  bounds.extend(empPos);

  const chegada = { '1°': '05:45', '2°': '14:45', '3°': '20:55' }[mgTurno] || '';

  // Show sem-rota passengers as gray markers
  DATA.forEach(rota => {
    rota.passageiros.filter(p => p.status === 'sem-rota' && p.lat && p.lng).forEach(p => {
      const pos = new google.maps.LatLng(p.lat, p.lng);
      bounds.extend(pos);
      hasPoints = true;
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        title: p.nome + ' (Sem Rota)',
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#9ca3af', fillOpacity: 0.8, strokeColor: '#fff', strokeWeight: 2 },
        zIndex: 30
      });
      marker.addListener('click', () => {
        mgInfoWindow.setContent(`<div style="color:#000;min-width:180px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid #9ca3af;padding-bottom:4px;margin-bottom:6px">Sem Rota</div>
          <div style="font-weight:600">${p.nome}</div>
          <div style="font-size:11px;color:#555">${p.embarque||p.endereco||'—'}</div>
          <div style="font-size:11px;color:#555">${p.bairro||''} · ${p.cidade||''}</div>
          ${p.telefone ? `<div style="font-size:11px;color:#555">${p.telefone}</div>` : ''}
        </div>`);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });
  });

  // Show extra route if requested
  if (rotaExtraIdx !== undefined && ROTAS_EXTRAS[rotaExtraIdx]) {
    const re = ROTAS_EXTRAS[rotaExtraIdx];
    const reColor = '#ec4899';
    legend.innerHTML += `<div style="display:flex;align-items:center;gap:6px">
      <div style="width:14px;height:14px;border-radius:50%;background:${reColor};flex-shrink:0"></div>
      <span style="color:var(--text)">${re.nome}</span>
      <span style="color:var(--muted)">${re.passageiros.length} pass.</span>
    </div>`;
    re.passageiros.filter(p => p.lat && p.lng).forEach((p, i) => {
      const pos = new google.maps.LatLng(p.lat, p.lng);
      bounds.extend(pos);
      hasPoints = true;
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        label: { text: String(i+1), color: '#000', fontSize: '10px', fontWeight: '700' },
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: 12, fillColor: reColor, fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
        zIndex: 80
      });
      marker.addListener('click', () => {
        mgInfoWindow.setContent(`<div style="color:#000;min-width:180px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid ${reColor};padding-bottom:4px;margin-bottom:6px">${re.nome}</div>
          <div style="font-weight:600">${p.nome}</div>
          <div style="font-size:11px;color:#555">${p.embarque||p.endereco||'—'}</div>
          ${p.telefone ? `<div style="font-size:11px;color:#555">${p.telefone}</div>` : ''}
        </div>`);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });
  }

  for (let ri = 0; ri < rotas.length; ri++) {
    const rota = rotas[ri];
    const color = MG_COLORS[rota.linha] || '#fff';
    const passAtivos = rota.passageiros
      .filter(p => p.status === 'ativo' && p.lat && p.lng)
      .sort((a,b) => (a.horario||'99:99').localeCompare(b.horario||'99:99'));

    if (passAtivos.length === 0) continue;
    hasPoints = true;

    // Legend item
    legend.innerHTML += `<div style="display:flex;align-items:center;gap:6px">
      <div style="width:14px;height:14px;border-radius:50%;background:${color};flex-shrink:0"></div>
      <span style="color:var(--text)">Linha ${rota.linha}</span>
      <span style="color:var(--muted)">${passAtivos.length} pass.</span>
    </div>`;

    // Group passengers by coordinate (same point = multiple passengers)
    const coordGroups = new Map();
    passAtivos.forEach((p, i) => {
      const key = p.lat.toFixed(5) + ',' + p.lng.toFixed(5);
      if (!coordGroups.has(key)) coordGroups.set(key, []);
      coordGroups.get(key).push({...p, ordem: i+1});
    });

    // One marker per unique coordinate
    coordGroups.forEach((passengers, key) => {
      const [lat, lng] = key.split(',').map(Number);
      const pos = new google.maps.LatLng(lat, lng);
      bounds.extend(pos);
      const isMulti = passengers.length > 1;
      const label = isMulti ? String(passengers.length) : String(passengers[0].ordem);
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        title: passengers.map(p => p.nome).join(', '),
        label: { text: label, color: '#000', fontSize: '10px', fontWeight: '700' },
        icon: {
          path: google.maps.SymbolPath.CIRCLE,
          scale: isMulti ? 14 : 11,
          fillColor: color,
          fillOpacity: 0.9,
          strokeColor: isMulti ? '#fff' : '#fff',
          strokeWeight: isMulti ? 2.5 : 1.5
        },
        zIndex: isMulti ? 60 : 50
      });
      marker.addListener('click', () => {
        let html = `<div style="color:#000;min-width:200px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid ${color};padding-bottom:4px;margin-bottom:8px">
            Linha ${rota.linha} · ${rota.turno} Turno
            ${isMulti ? `<span style="background:${color};color:#000;border-radius:4px;padding:1px 6px;font-size:10px;margin-left:6px">${passengers.length} passageiros</span>` : ''}
          </div>
          <div style="font-size:11px;color:#555;margin-bottom:8px">${passengers[0].embarque||passengers[0].endereco||'—'}</div>`;
        passengers.forEach(p => {
          html += `<div style="border-top:1px solid #eee;padding-top:6px;margin-top:6px">
            <div style="font-weight:600;font-size:13px">${p.nome}</div>
            <div style="font-size:11px;color:#555">${p.horario||'--:--'}${p.telefone ? ' · ' + p.telefone : ''}</div>
            <div style="font-size:11px;color:#888">${p.bairro||''} · ${p.cidade||''}</div>
          </div>`;
        });
        html += '</div>';
        mgInfoWindow.setContent(html);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });

    // Draw route if enabled - with delay to avoid OVER_QUERY_LIMIT
    if (showRoutes && passAtivos.length > 0) {
      await new Promise(resolve => setTimeout(resolve, ri * 300)); // 300ms delay per route
      const directionsService = new google.maps.DirectionsService();

      await new Promise(resolve => {
        directionsService.route({
          origin: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
          destination: new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng),
          waypoints: (() => {
            const seen = new Set();
            return passAtivos.filter(p => {
              const k = p.lat.toFixed(5)+','+p.lng.toFixed(5);
              return seen.has(k) ? false : (seen.add(k), true);
            }).map(p => ({ location: new google.maps.LatLng(p.lat, p.lng), stopover: false }));
          })(),
          travelMode: google.maps.TravelMode.DRIVING,
          optimizeWaypoints: false,
        }, (result, status) => {
          if (status === 'OK') {
            console.log('Directions OK L' + rota.linha + ' ' + rota.turno + ' (' + passAtivos.length + ' waypoints)');
            const renderer = new google.maps.DirectionsRenderer({
              map: mgMap,
              directions: result,
              suppressMarkers: true,
              polylineOptions: {
                strokeColor: color,
                strokeWeight: 3,
                strokeOpacity: 0.75
              }
            });
            mgDirectionsRenderers.push(renderer);
          } else {
            console.warn('Directions fallback L' + rota.linha + ' ' + rota.turno + ':', status, '| waypoints:', passAtivos.length);
            // Fallback: straight polyline
            const path = [
              new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
              ...passAtivos.map(p => new google.maps.LatLng(p.lat, p.lng)),
              new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng)
            ];
            const poly = new google.maps.Polyline({
              path, map: mgMap,
              strokeColor: color, strokeWeight: 2, strokeOpacity: 0.6,
              icons: [{ icon: { path: 'M 0,-1 0,1', strokeOpacity: 1, scale: 3 }, offset: '0', repeat: '15px' }]
            });
            mgPolylines.push(poly);
          }
          resolve();
        });
      });
    }
  }

  if (hasPoints) {
    mgMap.fitBounds(bounds, { padding: 40 });
  }

  // Add chegada time to legend
  if (legend.innerHTML) {
    legend.innerHTML = `<span style="color:var(--muted);margin-right:8px">Chegada: <strong style="color:var(--text)">${chegada}</strong></span>` + legend.innerHTML;
    legend.innerHTML += `<span style="color:var(--muted);margin-left:auto;font-size:11px">Garagem &nbsp; Empresa</span>`;
  } else {
    legend.innerHTML = '<span style="color:var(--muted)">Nenhuma linha selecionada para este turno</span>';
  }
}




// ---- ROTAS EXTRAS ----
let rePassSelecionados = []; // {nome, lat, lng, horario, telefone, bairro, cidade, embarque}

// ---- SEM ROTA ----
let semRotaPassIdx = null; // {rotaId, passIdx}

// ---- BACKUP ----

// ---- CLIENTE AUTH ----
const SENHA_CLIENTE = C.senhaFallback; // fallback se o config nao tiver senha definida

// A senha do Config chega do Firebase de forma assincrona. Ate ela chegar NAO
// podemos concluir que o acesso lembrado esta invalido: comparar cedo demais
// apagava o lembrete e quebrava a auto-entrada vinda do portal.
let _cfgSenhaLida = false;
let _resolverAuto;
const autoEntradaDecidida = new Promise(r => { _resolverAuto = r; });

// Busca a senha definida pelo gestor (Config > Senha da empresa cliente) no Firebase.
(async () => {
  try {
    const { initializeApp, getApps, getApp } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js');
    const { getFirestore, doc, getDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const app = getApps().find(a => a.name === FB_APP_NOME) || initializeApp(FB_CONFIG, FB_APP_NOME);
    // App Check e sessao, nesta ordem, antes de qualquer acesso ao Firestore.
    // Sem sessao o Firestore recusa tudo — e no PIN a recusa vira
    // "voce ja tem um PIN cadastrado", que e mentira.
    if (window.temviaComum) await window.temviaComum.prepararFirebase(app);
    const db = getFirestore(app);
    const snap = await getDoc(doc(db, CLIENTE_ID, 'config'));
    // a mesma leitura ja traz os turnos: sem isso o cliente mostra
    // "chegada undefined" para qualquer turno cadastrado depois
    if (snap.exists()) {
      const d = snap.data();
      if (d.turnosChegada) Object.assign(TURNOS_CHEGADA, d.turnosChegada);
      if (Array.isArray(d.turnos) && d.turnos.length) TURNOS = d.turnos;
      // A mesma leitura traz quem opera e quem e atendido. Antes o portal
      // mostrava o apelido da casca ("EVAMO TESTE"), que e texto fixo do
      // arquivo e nao o que o gestor cadastrou.
      const emp = d.empresa || {};
      cliAplicarIdentidade(emp.nome || d.nome || '', emp.operacaoNome || d.operacaoNome || '');
    }
    const sc = snap.exists() ? (snap.data().senhaCliente || '') : '';
    if (sc) window._senhaClienteCfg = sc; // quando definida no config, ela passa a valer
  } catch(e) { /* sem rede: usa o fallback */ }
  _cfgSenhaLida = true;
  tentarAutoEntradaCliente();
  _resolverAuto();
})();

// Entrada automatica: o portal temvia guarda a senha validada; se ela confere, pula a tela de senha.
function tentarAutoEntradaCliente() {
  try {
    const salva = localStorage.getItem('temvia_cliente_senha_' + CLIENTE_ID) || '';
    const alvo = window._senhaClienteCfg || SENHA_CLIENTE;
    const overlay = document.getElementById('loginOverlay');
    if (salva && salva === alvo && overlay && overlay.style.display !== 'none') {
      overlay.style.display = 'none';
      window._clienteLiberado = true;
      MAPS_API_KEY = '';
      getApiKey();
      loadDataRealtime();
    } else if (_cfgSenhaLida && salva && salva !== alvo) {
      localStorage.removeItem('temvia_cliente_senha_' + CLIENTE_ID); // senha mudou: pedir de novo
    }
  } catch(e) {}
}
tentarAutoEntradaCliente();

let fbAuthCli = null;
async function initAuthCli() {
  if (fbAuthCli) return fbAuthCli;
  const { initializeApp, getApps } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js');
  const { getAuth } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
  const app = getApps().find(a => a.name === FB_APP_NOME) || initializeApp(FB_CONFIG, FB_APP_NOME);
  // App Check e sessao, nesta ordem, antes de qualquer acesso ao Firestore.
  // Sem sessao o Firestore recusa tudo — e no PIN a recusa vira
  // "voce ja tem um PIN cadastrado", que e mentira.
  if (window.temviaComum) await window.temviaComum.prepararFirebase(app);
  fbAuthCli = getAuth(app);
  return fbAuthCli;
}

// Quem pode entrar: lista mantida pelo gestor em {CLIENTE_ID}/acessos
// -> { lista: [ { email, nome, papel: 'cliente', ativo: true } ] }
// Tres estados, nunca dois. Ver o cabecalho do patch.
const ACESSO = { AUTORIZADO: 'AUTHORIZED', NEGADO: 'DENIED', INDISPONIVEL: 'UNAVAILABLE' };

async function acessoDoEmail(email) {
  try {
    const { getFirestore, doc, getDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const auth = await initAuthCli();
    const snap = await getDoc(doc(getFirestore(auth.app), CLIENTE_ID, 'acessos'));
    const lista = snap.exists() ? (snap.data().lista || []) : [];
    const alvo = (email || '').trim().toLowerCase();
    const achado = lista.find(u => (u.email || '').trim().toLowerCase() === alvo) || null;
    const ok = !!(achado && achado.papel === 'cliente' && achado.ativo !== false);
    return { estado: ok ? ACESSO.AUTORIZADO : ACESSO.NEGADO, acesso: achado };
  } catch (e) {
    // NAO deu para perguntar. Isso nao e uma negativa.
    console.warn('[temvia] Nao foi possivel verificar o acesso:', e && e.message);
    return { estado: ACESSO.INDISPONIVEL, acesso: null };
  }
}

function clientePodeEntrar(r) {
  return !!(r && r.estado === ACESSO.AUTORIZADO);
}

// Servidor fora do ar na hora de conferir o acesso. Nao acusa ninguem: diz o
// que aconteceu e oferece tentar de novo.
function cliAvisoIndisponivel() {
  mostrarFormularioCliente();
  const err = document.getElementById('loginError');
  if (err) {
    err.innerHTML =
      'N\u00e3o foi poss\u00edvel verificar seu acesso agora. ' +
      'Verifique sua conex\u00e3o e tente novamente.' +
      '<div style="margin-top:10px"><button onclick="location.reload()" ' +
      'style="padding:8px 18px;border-radius:8px;border:0;background:var(--accent);' +
      'color:#000;font-weight:700;cursor:pointer">Tentar novamente</button></div>';
    err.style.display = 'block';
  }
}

function liberarPortalCliente() {
  const overlay = document.getElementById('loginOverlay');
  if (overlay) overlay.style.display = 'none';
  window._clienteLiberado = true;
  MAPS_API_KEY = '';
  getApiKey();
  loadDataRealtime();
}

function verSenhaCliente() {
  const campo = document.getElementById('senhaCliente');
  const botao = document.getElementById('olhoCliente');
  if (!campo) return;
  const mostrando = campo.type === 'password';
  campo.type = mostrando ? 'text' : 'password';
  if (botao) {
    botao.innerHTML = mostrando ? "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round' style='width:18px;height:18px;display:block'><path d='M3 3l18 18'/><path d='M10.6 6.2A9.9 9.9 0 0 1 12 6c6.5 0 10 6 10 6a17 17 0 0 1-3.2 3.9'/><path d='M6.6 6.7A17 17 0 0 0 2 12s3.5 6 10 6a9.6 9.6 0 0 0 3.9-.8'/><path d='M9.9 9.9a3 3 0 0 0 4.2 4.2'/></svg>" : "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round' style='width:18px;height:18px;display:block'><path d='M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z'/><circle cx='12' cy='12' r='3'/></svg>";
    botao.title = mostrando ? 'Ocultar senha' : 'Mostrar senha';
    botao.setAttribute('aria-label', botao.title);
  }
}


// Portal da transportadora: e para la que mandamos quem chega sem sessao.
// Portal da transportadora: e para la que mandamos quem chega sem sessao.
// Vem da CASCA. Sem portalUrl declarado (ambiente de teste), o app mostra o
// proprio formulario em vez de redirecionar — senao a casca de teste vira
// beco sem saida, devolvendo para o portal de producao.
const PORTAL_URL = (window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.portalUrl) || '';
function irParaPortal(usarReplace) {
  if (!PORTAL_URL) return false;              // sem portal: quem chama mostra o form
  if (usarReplace) window.location.replace(PORTAL_URL);
  else window.location.href = PORTAL_URL;
  return true;
}
let _semAcessoNestaEmpresa = false;

// Evita o "pisca": o formulario so aparece quando confirmamos que nao ha sessao aberta.
let _formMostrado = false;
// Expostas no window porque quem chama (logout) esta fora deste IIFE.
window.irParaPortal = function () { return irParaPortal.apply(null, arguments); };
window.mostrarFormularioCliente = function () { return mostrarFormularioCliente.apply(null, arguments); };

function mostrarFormularioCliente() {
  if (_formMostrado) return;
  _formMostrado = true;
  const chk = document.getElementById('loginChecando');
  const box = document.getElementById('loginBox');
  if (chk) chk.style.display = 'none';
  if (box) box.style.display = '';
}
// Rede lenta ou fora do ar: nao deixa o usuario preso no "Verificando".
setTimeout(mostrarFormularioCliente, 3500);

function msgCliente(texto, erro) {
  const el = document.getElementById('loginMsg');
  if (!el) return;
  el.style.color = erro ? 'var(--red)' : '#10b981';
  el.textContent = texto || '';
}

async function fazerLogin() {
  const email = (document.getElementById('emailCliente').value || '').trim();
  const val = document.getElementById('senhaCliente').value;
  const err = document.getElementById('loginError');
  const btn = document.getElementById('btnEntrarCliente');
  err.style.display = 'none';
  msgCliente('');
  mostrarFormularioCliente();

  // Sem e-mail: senha unica da empresa (caminho antigo, vale ate todos terem conta propria).
  if (!email) {
    if (val === (window._senhaClienteCfg || SENHA_CLIENTE)) {
      try { localStorage.setItem('temvia_cliente_senha_' + CLIENTE_ID, val); } catch(e) {}
      liberarPortalCliente();
    } else {
      err.textContent = 'Senha incorreta. Se voce ja tem conta propria, informe tambem o e-mail.';
      err.style.display = 'block';
      document.getElementById('senhaCliente').value = '';
    }
    return;
  }

  // Com e-mail: conta individual (Firebase Auth) + conferencia do perfil.
  btn.disabled = true; btn.textContent = 'Entrando...';
  try {
    const auth = await initAuthCli();
    const { signInWithEmailAndPassword, signOut } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await signInWithEmailAndPassword(auth, email, val);
    const acesso = await acessoDoEmail(email);
    if (!clientePodeEntrar(acesso)) {
      await signOut(auth);
      if (!acesso) err.textContent = 'Login correto, mas voce ainda nao esta na lista de acessos desta empresa.';
      else if (acesso.papel !== 'cliente') err.textContent = 'Login correto, mas o perfil cadastrado nao e de empresa cliente. Peca ao gestor para conferir o campo papel.';
      else err.textContent = 'Login correto, mas este acesso esta desativado. Fale com o gestor.';
      err.style.display = 'block';
      return;
    }
    liberarPortalCliente();
  } catch (e) {
    const map = {
      'auth/invalid-email': 'E-mail invalido.',
      'auth/user-not-found': 'Usuario nao encontrado.',
      'auth/wrong-password': 'Senha incorreta.',
      'auth/invalid-credential': 'E-mail ou senha incorretos.',
      'auth/too-many-requests': 'Muitas tentativas. Tente de novo em alguns minutos.'
    };
    err.textContent = map[e && e.code] || ('Erro ao entrar: ' + ((e && e.message) ? e.message : e));
    err.style.display = 'block';
  } finally {
    btn.disabled = false; btn.textContent = 'Entrar';
  }
}

// Autosservico: o proprio usuario redefine a senha, sem passar pelo gestor.
async function esqueciSenhaCliente() {
  const email = (document.getElementById('emailCliente').value || '').trim();
  const err = document.getElementById('loginError');
  err.style.display = 'none';
  if (!email) { msgCliente('Digite seu e-mail no campo acima e clique de novo.', true); return; }
  try {
    const auth = await initAuthCli();
    const { sendPasswordResetEmail } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await sendPasswordResetEmail(auth, email);
    msgCliente('Enviamos um link para voce criar uma senha nova. Confira tambem o spam.', false);
  } catch (e) {
    msgCliente('Nao foi possivel enviar: ' + ((e && e.code) ? e.code : e), true);
  }
}

// Sessao ja aberta neste aparelho (ou vinda do portal temvia): entra direto.
(async () => {
  try {
    const auth = await initAuthCli();
    const { onAuthStateChanged } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    onAuthStateChanged(auth, async (user) => {
      await autoEntradaDecidida;   // espera a senha do Config antes de decidir
      const overlay = document.getElementById('loginOverlay');
      // Ja entrou (sessao anterior ou senha unica lembrada): nao mexe.
      if (!overlay || overlay.style.display === 'none') return;
      // Sessao anonima NAO e login. Ver o cabecalho do patch.
      if (user && user.isAnonymous) user = null;
      if (!user) {
        // Sem sessao: a porta de entrada e o PORTAL, nao o login deste app.
        // replace() para o botao "voltar" nao ficar pingando entre os dois.
        if (_semAcessoNestaEmpresa || !irParaPortal(true)) mostrarFormularioCliente();
        else mostrarFormularioCliente();
        return;
      }
      const r = await acessoDoEmail(user.email);
      if (r.estado === ACESSO.AUTORIZADO) { liberarPortalCliente(); return; }

      _semAcessoNestaEmpresa = true;   // precisa LER o motivo: nao redireciona
      if (r.estado === ACESSO.INDISPONIVEL) cliAvisoIndisponivel();
      else {
        const err = document.getElementById('loginError');
        if (err) {
          err.textContent = 'Este login nao tem acesso ao portal desta empresa. Fale com o gestor.';
          err.style.display = 'block';
        }
        mostrarFormularioCliente();
      }
    });
  } catch (e) { mostrarFormularioCliente(); }   // Firebase fora do ar: login local como reserva

})();

async function logout() {
  if (fbUnsub) { fbUnsub(); fbUnsub = null; }
  try { localStorage.removeItem('temvia_cliente_senha_' + CLIENTE_ID); } catch(e) {}
  try {
    const auth = await initAuthCli();
    const { signOut } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await signOut(auth);
  } catch (e) {}
  // Porta da frente do sistema agora e o portal temvia, nao a tela de login do app.
  // As duas funcoes moram dentro do IIFE de autenticacao; daqui so se
  // alcanca pelo window. Antes a chamada crua matava o botao Sair.
  const _ir = window.irParaPortal, _form = window.mostrarFormularioCliente;
  if (!(typeof _ir === 'function' && _ir(false))) {
    if (typeof _form === 'function') _form();
    else location.reload();
  }
}

let fbUnsub = null;

// ===========================================================================
// ESTADO DE CARREGAMENTO DO CADASTRO
// Regra: a tela nunca mostra dado sem dizer de onde ele veio.
// ===========================================================================

// Quanto tempo esperar o servidor antes de recorrer ao cache.
const CLI_ESPERA_MS = 8000;

// Ate quando um cache ainda serve. 24 horas: fretamento muda todo dia, e um
// retrato de anteontem apresentado como operacional engana mais do que ajuda.
const CACHE_CLIENTE_MAX_AGE_MS = 24 * 60 * 60 * 1000;

// Fuso da OPERACAO, nao do aparelho. Vem da casca para nao virar premissa
// eterna do produto: outra transportadora, outro fuso.
const OPERATION_TIMEZONE =
  (window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.timezone) || 'America/Sao_Paulo';

// null enquanto nada foi renderizado; depois 'servidor' ou 'cache'.
let CLI_ORIGEM = null;

function cliPainel() {
  let el = document.getElementById('cliEstado');
  if (!el) {
    el = document.createElement('div');
    el.id = 'cliEstado';
    el.style.cssText = 'position:fixed;inset:0;z-index:9998;display:flex;' +
      'align-items:center;justify-content:center;flex-direction:column;gap:14px;' +
      'background:var(--bg,#0d1117);color:var(--text,#e6edf3);' +
      'font-family:Inter,system-ui,sans-serif;text-align:center;padding:32px';
    document.body.appendChild(el);
  }
  return el;
}

function cliEstadoCarregando() {
  const el = cliPainel();
  el.style.display = 'flex';
  el.innerHTML = '<div style="font-size:15px;font-weight:600">Carregando os dados da opera\u00e7\u00e3o\u2026</div>' +
    '<div style="font-size:13px;opacity:.7">Buscando no servidor.</div>';
}

function cliEstadoPronto() {
  const el = document.getElementById('cliEstado');
  if (el) el.style.display = 'none';
  cliTarjaCache(null);
}

function cliEstadoErro(motivo) {
  const el = cliPainel();
  el.style.display = 'flex';
  el.innerHTML =
    '<div style="font-size:15px;font-weight:600">N\u00e3o foi poss\u00edvel carregar os dados</div>' +
    '<div style="font-size:13px;opacity:.75;max-width:380px">' + (motivo || '') +
    ' N\u00e3o h\u00e1 c\u00f3pia local recente para mostrar.</div>' +
    '<button onclick="location.reload()" style="margin-top:6px;padding:9px 18px;' +
    'border-radius:8px;border:0;background:var(--brand,#FFB000);color:#000;' +
    'font-weight:700;cursor:pointer">Tentar de novo</button>';
}

// Tarja permanente enquanto a tela estiver mostrando cache. Passar null remove.
function cliTarjaCache(quando) {
  let t = document.getElementById('cliTarjaCache');
  if (!quando) { if (t) t.remove(); return; }
  if (!t) {
    t = document.createElement('div');
    t.id = 'cliTarjaCache';
    t.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:9997;' +
      'padding:9px 14px;background:#b45309;color:#fff;font-size:12.5px;' +
      'font-family:Inter,system-ui,sans-serif;text-align:center;line-height:1.4';
    document.body.appendChild(t);
  }
  t.textContent = 'Exibindo dados salvos em ' + quando +
    '. N\u00e3o foi poss\u00edvel atualizar as informa\u00e7\u00f5es agora.';
}

// Sempre no fuso da opera\u00e7\u00e3o, nunca no do aparelho. Celular com fuso errado
// (ou gestor viajando) mostraria uma hora que n\u00e3o corresponde a nada.
function cliFormataQuando(iso) {
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return null;
    return d.toLocaleString('pt-BR', {
      timeZone: OPERATION_TIMEZONE,
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit'
    }).replace(', ', ' \u00e0s ');
  } catch (e) { return null; }
}

// Servidor fora do ar ou lento: usa o cache, se houver e se ainda valer.
function cliCairParaCache(motivo) {
  if (CLI_ORIGEM) return;              // ja tem dado do servidor na tela
  let snap = null;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) snap = JSON.parse(raw);
  } catch (e) {}

  if (!snap || !snap.DATA || !snap.DATA.length) { cliEstadoErro(motivo); return; }

  const quando = cliFormataQuando(snap.savedAt);
  if (!quando) { cliEstadoErro(motivo); return; }

  const idade = Date.now() - new Date(snap.savedAt).getTime();
  if (idade > CACHE_CLIENTE_MAX_AGE_MS) {
    cliEstadoErro(motivo + ' A c\u00f3pia local \u00e9 de ' + quando +
      ' e j\u00e1 passou de 24 horas \u2014 n\u00e3o serve como informa\u00e7\u00e3o atual.');
    return;
  }

  applySnapshot(snap);
  CLI_ORIGEM = 'cache';
  const el = document.getElementById('cliEstado');
  if (el) el.style.display = 'none';
  renderSidebar();
  updateStats();
  cliTarjaCache(quando);
  console.warn('Renderizado a partir do cache de', quando, '\u2014', motivo);
}

async function loadDataRealtime() {
  // Nada de desenhar antes de ter dado de verdade. A ordem e:
  // carregando -> servidor -> (se falhar) cache identificado -> (se nao houver) erro.
  cliEstadoCarregando();

  // Se o servidor nao responder em CLI_ESPERA_MS, cai para o cache. Sem isto,
  // o onSnapshot pendurado deixa a tela em "Carregando" para sempre.
  const relogio = setTimeout(function () {
    if (!CLI_ORIGEM) cliCairParaCache('O servidor demorou a responder.');
  }, CLI_ESPERA_MS);

  try {
    const ok = await initFirebase();
    if (ok && fbDb && fbDocRef) {
      const { onSnapshot } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
      fbUnsub = onSnapshot(fbDocRef, (snap) => {
        if (snap.exists()) {
          const saved = snap.data();
          if (saved.DATA && saved.DATA.length > 0) {
            DATA.length = 0; saved.DATA.forEach(r => DATA.push(r));
            if (saved.MOTORISTAS) { MOTORISTAS.length = 0; saved.MOTORISTAS.forEach(m => MOTORISTAS.push(m)); }
            clearTimeout(relogio);
            saveToLocal(saved);              // o cache passa a ser alimentado aqui
            CLI_ORIGEM = 'servidor';
            cliEstadoPronto();
            renderSidebar();
            updateStats();
            if (activeId) selectLine(activeId);
            console.log('Dados atualizados do Firebase:', saved.savedAt);
          }
        }
      }, (err) => {
        console.warn('Firebase realtime error:', err.message);
        clearTimeout(relogio);
        cliCairParaCache('Nao foi possivel falar com o servidor.');
      });
      console.log('Firebase conectado — atualizações em tempo real ativas');
    } else {
      clearTimeout(relogio);
      cliCairParaCache('Sem conexão com o servidor.');
    }
  } catch(e) {
    console.warn('Firebase não disponível:', e.message);
    clearTimeout(relogio);
    cliCairParaCache('Sem conexão com o servidor.');
  }
}


