function cliResetNaoCadastrado() {
  CLI_NAO_CADASTRADO = false;
  const check = document.getElementById('cliNaoCadastradoCheck');
  const toggle = document.getElementById('cliNaoCadastradoToggle');
  const buscaArea = document.getElementById('cliBuscaArea');
  const aviso = document.getElementById('cliNaoCadastradoAviso');
  if (check) { check.textContent=''; check.style.background='transparent'; check.style.borderColor='var(--border)'; }
  if (toggle) { toggle.style.borderColor='var(--border)'; toggle.style.background='transparent'; }
  if (buscaArea) buscaArea.style.display='block';
  if (aviso) aviso.style.display='none';
}

function cliToggleNaoCadastrado() {
  CLI_NAO_CADASTRADO = !CLI_NAO_CADASTRADO;
  const check = document.getElementById('cliNaoCadastradoCheck');
  const toggle = document.getElementById('cliNaoCadastradoToggle');
  const buscaArea = document.getElementById('cliBuscaArea');
  const aviso = document.getElementById('cliNaoCadastradoAviso');

  if (CLI_NAO_CADASTRADO) {
    check.textContent = '✓';
    check.style.background = 'var(--accent)';
    check.style.borderColor = 'var(--accent)';
    check.style.color = '#000';
    toggle.style.borderColor = 'rgba(245,158,11,0.4)';
    toggle.style.background = 'rgba(245,158,11,0.06)';
    buscaArea.style.display = 'none';
    aviso.style.display = 'block';
    // Limpar selecionados
    CLI_FUNC_SELECIONADOS = [];
    cliRenderFuncSelecionados();
    const r = document.getElementById('cliResultadoFunc');
    if (r) r.style.display = 'none';
    const b = document.getElementById('cliBuscaFunc');
    if (b) b.value = '';
  } else {
    check.textContent = '';
    check.style.background = 'transparent';
    check.style.borderColor = 'var(--border)';
    toggle.style.borderColor = 'var(--border)';
    toggle.style.background = 'transparent';
    buscaArea.style.display = 'block';
    aviso.style.display = 'none';
  }
}
