function cliMontarResumo() {
  const data = document.getElementById('cliData').value;
  const horario = document.getElementById('cliHorario').value;
  const dataFmt = data ? new Date(data+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'}) : '—';
  document.getElementById('cliResumo').innerHTML =
    '<div style="display:flex;flex-direction:column;gap:8px">' +
    '<div><span style="color:var(--muted);font-size:11px">SERVIÇO</span><br><strong>' + CLI_TIPO_LABEL + '</strong></div>' +
    '<div><span style="color:var(--muted);font-size:11px">DATA</span><br><strong>' + dataFmt + '</strong></div>' +
    '<div><span style="color:var(--muted);font-size:11px">HORÁRIO</span><br><strong>' + horario + '</strong></div>' +
    '<div><span style="color:var(--muted);font-size:11px">ROTEIRO</span><br><strong>' + CLI_ROTEIRO + '</strong></div>' +
    '<div><span style="color:var(--muted);font-size:11px">FUNCIONÁRIOS (' + (CLI_NAO_CADASTRADO ? 'não cadastrado' : CLI_FUNC_SELECIONADOS.length) + ')</span><br>' +
    (CLI_NAO_CADASTRADO
      ? '<span style="font-size:12px;color:var(--accent)">Passageiro não cadastrado — ver observação</span>'
      : CLI_FUNC_SELECIONADOS.map((p,i) => {
      const nome = typeof p === 'string' ? p : (p.nome || '');
      const linha = typeof p === 'object' ? (p.linha || '') : '';
      const turno = typeof p === 'object' ? (p.turno || '') : '';
      const bairro = typeof p === 'object' ? (p.bairro || '') : '';
      return '<span style="font-size:12px">' + (i+1) + '. ' + nome +
        (linha ? ' · Linha ' + linha : '') +
        (turno ? ' · ' + turno + ' Turno' : '') +
        (bairro ? ' · ' + bairro : '') +
        '</span>';
    }).join('<br>')) + '</div>' +
    '</div>';
}

function cliBuscarFuncionarios() {
  const q = document.getElementById('cliBuscaFunc').value.toLowerCase().trim();
  const div = document.getElementById('cliResultadoFunc');
  if (!q) { div.style.display='none'; return; }

  const todos = [];
  DATA.forEach(rota => {
    rota.passageiros.filter(p => p.status === 'ativo').forEach(p => {
      todos.push({ nome: p.nome, bairro: p.bairro, cidade: p.cidade, linha: rota.linha, turno: rota.turno });
    });
  });

  const found = todos.filter(p =>
    [p.nome, p.bairro, p.cidade].map(x => (x||'').toLowerCase()).join(' ').includes(q)
  ).slice(0, 15);

  if (!found.length) {
    div.innerHTML = '<div style="padding:12px;font-size:12px;color:var(--muted)">Nenhum resultado.</div>';
    div.style.display = 'block'; return;
  }

  div.style.display = 'block';
  window._cliBuscaResultados = found;
  div.innerHTML = '';

  found.forEach((p, idx) => {
    const jaSel = CLI_FUNC_SELECIONADOS.some(s => s.nome === p.nome);
    const item = document.createElement('div');
    item.style.cssText = 'padding:12px 14px;cursor:pointer;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;background:' + (jaSel ? 'rgba(245,158,11,0.08)' : 'transparent') + ';transition:background 0.1s';
    item.innerHTML =
      '<div>' +
        '<div style="font-size:14px;font-weight:600">' + p.nome + '</div>' +
        '<div style="font-size:11px;color:var(--muted)">Linha ' + p.linha + ' · ' + p.turno + ' Turno' + (p.bairro ? ' · ' + p.bairro : '') + '</div>' +
      '</div>' +
      '<span style="font-size:22px;color:' + (jaSel ? 'var(--accent)' : 'var(--muted)') + '">' + (jaSel ? '' : '＋') + '</span>';
    item.addEventListener('click', function() {
      cliToggleFunc(idx);
    });
    div.appendChild(item);
  });
}

function cliToggleFunc(idx) {
  const p = window._cliBuscaResultados && window._cliBuscaResultados[idx];
  if (!p) return;
  const pos = CLI_FUNC_SELECIONADOS.findIndex(s => s.nome === p.nome);
  if (pos >= 0) CLI_FUNC_SELECIONADOS.splice(pos, 1);
  else CLI_FUNC_SELECIONADOS.push({
    nome:   p.nome  || '',
    linha:  p.linha || '',
    turno:  p.turno || '',
    bairro: p.bairro|| ''
  });
  cliRenderFuncSelecionados();
  cliBuscarFuncionarios();
}

function cliRenderFuncSelecionados() {
  const div = document.getElementById('cliFuncSelecionados');
  if (!div) return;
  if (!CLI_FUNC_SELECIONADOS.length) {
    div.innerHTML = '<span style="font-size:12px;color:var(--muted);font-style:italic">Nenhum selecionado ainda</span>';
    return;
  }
  div.innerHTML = CLI_FUNC_SELECIONADOS.map((p, i) =>
    `<div style="display:flex;align-items:center;gap:6px;background:rgba(245,158,11,0.1);border:1px solid rgba(245,158,11,0.3);border-radius:20px;padding:5px 10px;font-size:12px">
      <span style="background:var(--accent);color:#000;border-radius:50%;width:16px;height:16px;display:inline-flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;flex-shrink:0">${i+1}</span>
      <span>${p.nome.split(' ').slice(0,2).join(' ')}${p.linha?' · L'+p.linha:''}${p.turno?' · '+p.turno[0]+'T':''}</span>
      <button onclick="cliRemoverFunc(${i})" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:15px;line-height:1;padding:0 2px">×</button>
    </div>`
  ).join('');
}

function cliRemoverFunc(idx) {
  CLI_FUNC_SELECIONADOS.splice(idx, 1);
  cliRenderFuncSelecionados();
  cliBuscarFuncionarios();
}

