async function cliCarregarSolicitacoes() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) return;
    const { onSnapshot, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    onSnapshot(doc(fbDb, CLIENTE_ID, 'solicitacoes_extras'), snap => {
      CLI_SOL_DADOS = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
      if (document.getElementById('cliAbaAcompanhamento').style.display !== 'none') cliRenderAcompanhamento();
    });
  } catch(e) { console.warn('CLI SOL:', e.message); }
}

async function cliEnviarSolicitacao() {
  const data = document.getElementById('cliData').value;
  const horario = document.getElementById('cliHorario').value;
  const obs = document.getElementById('cliObs').value.trim();
  const msg = document.getElementById('cliMsg');

  if (!data) { msg.style.color='var(--red)'; msg.textContent='Informe a data.'; return; }
  if (!CLI_TIPO_KEY) { msg.style.color='var(--red)'; msg.textContent='Selecione o tipo de serviço.'; return; }
  if (!CLI_FUNC_SELECIONADOS.length && !CLI_NAO_CADASTRADO) { msg.style.color='var(--red)'; msg.textContent='Selecione ao menos um funcionário ou marque "Passageiro não cadastrado".'; return; }
  if (!CLI_ROTEIRO) { msg.style.color='var(--red)'; msg.textContent='Selecione o roteiro.'; return; }

  // Gerar ID único
  const now = new Date();
  const pad = n => String(n).padStart(2,'0');
  const idBase = 'SOL-' + now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate());
  const existentes = (CLI_SOL_DADOS||[]).filter(s => s.id.startsWith(idBase)).length;
  const id = idBase + '-' + String(existentes+1).padStart(3,'0');

  const dataFmt = new Date(data+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'});

  // Helper seguro para extrair dados do funcionário
  const getFuncData = p => typeof p === 'string'
    ? {nome:p, linha:'', turno:'', bairro:''}
    : {nome:p.nome||'', linha:p.linha||'', turno:p.turno||'', bairro:p.bairro||''};

  const funcItens = CLI_FUNC_SELECIONADOS.map(getFuncData);

  // Para e-mail e WhatsApp — lista numerada com detalhes
  const funcListaEmail = funcItens.map((f,i) =>
    (i+1) + '. ' + f.nome +
    (f.linha ? ' - Linha ' + f.linha : '') +
    (f.turno ? ' - ' + f.turno + ' Turno' : '') +
    (f.bairro ? ' - ' + f.bairro : '')
  ).join('\n');

  // Para exibição resumida inline
  const funcLista = funcItens.map(f =>
    f.nome + (f.linha ? ' (L'+f.linha+(f.turno?' '+f.turno[0]+'T':'')+(f.bairro?' '+f.bairro:'')+')' : '')
  ).join(', ');

  const nova = {
    id, data, horario,
    tipo: CLI_TIPO_KEY, tipoLabel: CLI_TIPO_LABEL,
    roteiro: CLI_ROTEIRO,
    funcionarios: funcItens.map(f => f.nome),
    funcionariosInfo: funcItens,
    naoCadastrado: CLI_NAO_CADASTRADO,
    obs, status: 'pendente',
    criadoEm: now.toISOString(),
    mesRef: data.slice(0,7)
  };

  msg.style.color='var(--muted)'; msg.textContent='Enviando...';

  try {
    // 1. Salvar no Firebase
    if (!fbDb) await initFirebase();
    if (!fbDb) throw new Error('Firebase indisponível');
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'solicitacoes_extras');
    const snap = await getDoc(ref);
    const lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    // Limpar undefined — Firebase não aceita esse valor
    const limpar = obj => JSON.parse(JSON.stringify(obj, (k,v) => v === undefined ? '' : v));
    lista.push(limpar(nova));
    await setDoc(ref, { lista: lista.map(limpar), updatedAt: now.toISOString() });

    // 2. Enviar e-mails via EmailJS (gestor + cliente)
    try {
      emailjs.init('i8-o88nerwgYStDgL');
      const params = {
        sol_id:       id,
        tipo:         CLI_TIPO_LABEL,
        data:         dataFmt,
        horario:      horario || '—',
        roteiro:      CLI_ROTEIRO,
        funcionarios: funcListaEmail,
        obs:          obs || '—',
      };
      // E-mail para o gestor Redentor
      console.log('Enviando e-mail para: redentorfretamento@gmail.com');
      await emailjs.send('service_gp46qeg', 'template_m4k9byn', { origem: C.origemEmail,
        ...params, to_email: 'redentorfretamento@gmail.com'
      });
      // E-mail para o cliente (teste: borbacana@gmail.com)
      console.log('Enviando e-mail para: borbacana@gmail.com');
      await emailjs.send('service_gp46qeg', 'template_m4k9byn', { origem: C.origemEmail,
        ...params, to_email: 'borbacana@gmail.com'
      });
    } catch(emailErr) {
      console.warn('EmailJS erro (não crítico):', emailErr);
    }

    // 3. Mostrar confirmação com botão WhatsApp
    const waTexto = encodeURIComponent(
      'Solicitacao enviada para ' + (EMPRESA_CONFIG.nome || 'a transportadora') + '.\n\n' +
      'ID: ' + id + '\n' +
      'Servico: ' + CLI_TIPO_LABEL + '\n' +
      'Data: ' + dataFmt + (horario ? ' as ' + horario : '') + '\n' +
      'Roteiro: ' + CLI_ROTEIRO + '\n' +
      'Funcionarios (' + funcItens.length + '):\n' +
      funcListaEmail +
      (obs ? '\n\nObs: ' + obs : '') +
      '\n\nAguardo confirmacao.'
    );
    const waUrl = cadWhatsUrl(waTexto);

    msg.innerHTML =
      '<div style="background:rgba(16,185,129,0.1);border:1px solid rgba(16,185,129,0.3);border-radius:12px;padding:16px;margin-top:8px;text-align:left">' +
        '<div style="font-weight:700;font-size:15px;color:var(--green);margin-bottom:8px">Solicitação enviada!</div>' +
        '<div style="font-size:13px;margin-bottom:4px"><strong>' + id + '</strong></div>' +
        '<div style="font-size:12px;color:var(--muted);margin-bottom:14px">' + cadDestinoTexto() + ' Compartilhe o número pelo WhatsApp se necessário:</div>' +
        '<a href="' + waUrl + '" target="_blank" style="display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;background:#25D366;color:#fff;border-radius:10px;text-decoration:none;font-family:Barlow,sans-serif;font-weight:800;font-size:14px;margin-bottom:10px">' +
          'Compartilhar pelo WhatsApp' +
        '</a>' +
        '<button onclick="cliNovaSolicitacao()" style="width:100%;padding:11px;border-radius:10px;border:1px solid var(--border);background:transparent;color:var(--text);font-size:14px;cursor:pointer;font-family:Barlow,sans-serif;font-weight:700">Nova Solicitação</button>' +
      '</div>';

    // Esconder o form e botões da etapa 4
    const btnEnviar = document.querySelector('#cliEtapa4 .add-btn');
    const btnVoltar = document.querySelector('#cliEtapa4 .btn-cancel');
    if (btnEnviar) btnEnviar.style.display = 'none';
    if (btnVoltar) btnVoltar.style.display = 'none';

    // Reset dados internos
    CLI_FUNC_SELECIONADOS = [];
    CLI_TIPO_KEY = ''; CLI_TIPO_LABEL = ''; CLI_ROTEIRO = '';
    const rf = document.getElementById('cliResultadoFunc');
    if (rf) rf.style.display = 'none';
    document.querySelectorAll('.cli-tipo-btn').forEach(b => b.classList.remove('selected'));

  } catch(e) {
    msg.style.color = 'var(--red)';
    msg.textContent = 'Erro ao enviar: ' + e.message;
  }
}

function cliNovaSolicitacao() {
  ['cliHorario','cliObs','cliBuscaFunc'].forEach(x => {
    const el = document.getElementById(x); if (el) el.value = '';
  });
  CLI_FUNC_SELECIONADOS = []; cliResetNaoCadastrado();
  CLI_TIPO_KEY = ''; CLI_TIPO_LABEL = ''; CLI_ROTEIRO = '';
  cliRenderFuncSelecionados();
  document.querySelectorAll('.cli-tipo-btn').forEach(b => b.classList.remove('selected'));
  ['rotBtn_entrada','rotBtn_saida','rotBtn_idavolta'].forEach(id => {
    const el = document.getElementById(id); if (el) el.classList.remove('selected');
  });
  const btnEnviar = document.querySelector('#cliEtapa4 .add-btn');
  const btnVoltar = document.querySelector('#cliEtapa4 .btn-cancel');
  if (btnEnviar) btnEnviar.style.display = '';
  if (btnVoltar) btnVoltar.style.display = '';
  const m = document.getElementById('cliMsg');
  if (m) m.innerHTML = '';
  cliGoEtapa(1);
}

function cliRenderAcompanhamento() {
  const filtroStatus = document.getElementById('cliFiltroStatus').value;
  const filtroMes = document.getElementById('cliFiltroMes').value;
  let lista = (CLI_SOL_DADOS || []).filter(s =>
    (!filtroStatus || s.status === filtroStatus) &&
    (!filtroMes || s.mesRef === filtroMes)
  ).sort((a,b) => (b.criadoEm||'').localeCompare(a.criadoEm||''));

  const div = document.getElementById('cliListaSolicitacoes');
  if (!lista.length) { div.innerHTML = '<div style="text-align:center;padding:32px;color:var(--muted)">Nenhuma solicitação encontrada.</div>'; return; }

  div.innerHTML = lista.map(s => {
    const st = CLI_SOL_STATUS[s.status] || CLI_SOL_STATUS.pendente;
    const dataFmt = s.data ? new Date(s.data+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'}) : '—';
    const podeCancelar = s.status === 'pendente';

    return `<div style="border:1px solid var(--border);border-left:4px solid ${st.cor};border-radius:10px;padding:14px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <div>
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap">
            <span style="font-family:'Barlow',sans-serif;font-size:11px;color:var(--muted);font-weight:700">${s.id}</span>
            <span style="background:${st.cor}22;color:${st.cor};border:1px solid ${st.cor}55;border-radius:6px;padding:2px 9px;font-size:12px;font-weight:700">${st.emoji} ${st.texto}</span>
          </div>
          <div style="font-weight:700;font-size:14px">${s.tipoLabel||s.tipo||'—'}</div>
          <div style="font-size:12px;color:var(--muted)">${dataFmt}${s.horario?' · '+s.horario:''}${s.turno?' · '+s.turno:''}${s.roteiro?' · '+s.roteiro:''}</div>
        </div>
        <div style="font-size:10px;color:var(--muted)">Solicitado em ${new Date(s.criadoEm||Date.now()).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</div>
      </div>
      ${s.funcionarios&&s.funcionarios.length?`<div style="font-size:12px;color:var(--muted);margin-bottom:6px">${s.funcionarios.join(', ')}</div>`:''}
      ${s.obs?`<div style="font-size:12px;color:var(--muted);margin-bottom:6px">${s.obs}</div>`:''}
      ${s.motorista?`<div style="font-size:12px;color:var(--green);margin-bottom:6px">Motorista: <strong>${s.motorista}</strong>${s.qtdVeiculos?' · '+s.qtdVeiculos+' veículo(s)':''}</div>`:''}
      ${podeCancelar?`<button onclick="cliCancelarSolicitacao('${s.id}')" class="btn-cancel" style="font-size:12px;padding:6px 14px;margin-top:6px">Cancelar solicitação</button>`:''}
    </div>`;
  }).join('');
}

async function cliCancelarSolicitacao(id) {
  if (!confirm('Cancelar esta solicitação?')) return;
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'solicitacoes_extras');
    const snap = await getDoc(ref);
    const lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    const sol = lista.find(s => s.id === id);
    if (sol) { sol.status = 'cancelada'; sol.canceledAt = new Date().toISOString(); }
    await setDoc(ref, { lista, updatedAt: new Date().toISOString() });
  } catch(e) { alert('Erro: ' + e.message); }
}
