let CAD_TIPO_KEY = '';
let CAD_TIPO_LABEL = '';
let CAD_DADOS = {};
let CAD_SOL_DADOS = [];
let CAD_PASSAGEIRO_SEL = null;
const CAD_FB_KEY = 'solicitacoes_cadastro';

function openCadastro() {
  try { cliMarcarNav('Cadastro'); } catch (e) {}
  const hoje = hojeLocal();
  document.getElementById('cadFiltroMes').value = hoje.slice(0,7);
  CAD_TIPO_KEY = ''; CAD_TIPO_LABEL = ''; CAD_DADOS = {}; CAD_PASSAGEIRO_SEL = null;
  document.querySelectorAll('#cadEtapa1 .cli-tipo-btn').forEach(b => b.classList.remove('selected'));
  document.getElementById('cadObs').value = '';
  document.getElementById('cadMsg').innerHTML = '';
  cadAba('nova'); cadGoEtapa(1); cadCarregarHistorico();
  document.getElementById('modalCadastro').classList.add('open');
}

function cadAba(aba) {
  const nova = document.getElementById('cadAbaNova');
  const hist = document.getElementById('cadAbaHistorico');
  nova.style.display = aba==='nova' ? 'flex' : 'none';
  nova.style.flexDirection = 'column';
  hist.style.display = aba==='historico' ? 'block' : 'none';
  ['cadTab1','cadTab2'].forEach((id,i) => {
    const btn = document.getElementById(id);
    const ativo = (i===0&&aba==='nova')||(i===1&&aba==='historico');
    btn.style.background = ativo?'var(--accent2)':'transparent';
    btn.style.color = ativo?'#fff':'var(--muted)';
    btn.style.border = ativo?'none':'1px solid var(--border)';
  });
  if (aba==='historico') cadRenderHistorico();
}

function cadGoEtapa(n) {
  if (n===3) { if (!cadValidarEtapa2()) return; cadMontarResumo(); }
  [1,2,3].forEach(i => { const el=document.getElementById('cadEtapa'+i); if(el) el.style.display=i===n?'block':'none'; });
  [1,2,3].forEach(i => { const d=document.getElementById('cadStep'+i+'Dot'); if(!d)return; d.className='cli-step'+(i<n?' done':i===n?' active':''); d.textContent=i<n?'✓':i; });
  [1,2].forEach(i => { const l=document.getElementById('cadLine'+i); if(l) l.className='cli-step-line'+(i<n?' done':''); });
  document.getElementById('modalCadastro').querySelector('.modal-box').scrollTop=0;
}

function cadGoEtapaVoltar(n) {
  [1,2,3].forEach(i => { const el=document.getElementById('cadEtapa'+i); if(el) el.style.display=i===n?'block':'none'; });
  [1,2,3].forEach(i => { const d=document.getElementById('cadStep'+i+'Dot'); if(!d)return; d.className='cli-step'+(i<n?' done':i===n?' active':''); d.textContent=i<n?'✓':i; });
  [1,2].forEach(i => { const l=document.getElementById('cadLine'+i); if(l) l.className='cli-step-line'+(i<n?' done':''); });
}

function cadSelecionarTipo(key, label, btn) {
  CAD_TIPO_KEY=key; CAD_TIPO_LABEL=label;
  document.querySelectorAll('#cadEtapa1 .cli-tipo-btn').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  document.getElementById('cadTipoTag').textContent=label;
  cadMontarFormulario();
  setTimeout(()=>cadGoEtapa(2),200);
}

function cadMontarFormulario() {
  const div=document.getElementById('cadFormulario');
  div.innerHTML=''; CAD_PASSAGEIRO_SEL=null;
  if (CAD_TIPO_KEY==='novo') {
    div.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
      <div style="grid-column:1/-1"><label class="form-label">Nome Completo *</label><input class="form-input" id="cadNome" placeholder="Nome completo" style="font-size:15px"></div>
      <div><label class="form-label">Telefone</label><input class="form-input" id="cadTelefone" placeholder="(15) 99999-9999"></div>
      <div><label class="form-label">Matrícula</label><input class="form-input" id="cadMatricula" placeholder="Matrícula do funcionário"></div>
      <div><label class="form-label">Data de Início *</label><input class="form-input" type="date" id="cadInicio"></div>
      <div style="grid-column:1/-1"><label class="form-label">Endereço Residencial</label><input class="form-input" id="cadEndereco" placeholder="Rua, número"></div>
      <div><label class="form-label">Bairro</label><input class="form-input" id="cadBairro" placeholder="Bairro"></div>
      <div><label class="form-label">Cidade</label><input class="form-input" id="cadCidade" placeholder="Cidade"></div>
      <div style="grid-column:1/-1"><label class="form-label">Turno de Trabalho *</label>
        <select class="form-input" id="cadTurno">${cadOpcoesTurno()}</select></div>
    </div>`;
    const d=document.getElementById('cadInicio'); if(d) d.value=hojeLocal();
  } else {
    div.innerHTML=`<div style="margin-bottom:12px">
      <label class="form-label">Buscar Passageiro</label>
      <input class="form-input" id="cadBuscaPass" type="text" placeholder="Digite o nome..." style="font-size:15px;margin-bottom:8px">
      <div id="cadResultadoPass" style="max-height:200px;overflow-y:auto;border:1px solid var(--border);border-radius:10px;display:none"></div>
    </div>
    <div id="cadPassSelecionado" style="display:none;background:var(--surface2);border-radius:10px;padding:14px;margin-bottom:12px">
      <div style="font-size:11px;color:var(--muted);margin-bottom:4px">PASSAGEIRO SELECIONADO</div>
      <div id="cadPassInfo"></div>
    </div>
    <div id="cadCamposEspecificos"></div>`;
    const inp=document.getElementById('cadBuscaPass');
    if (inp) inp.addEventListener('input', cadBuscarPassageiro);
  }
}

function cadBuscarPassageiro() {
  const inp=document.getElementById('cadBuscaPass'); if(!inp) return;
  const q=inp.value.toLowerCase().trim();
  const div=document.getElementById('cadResultadoPass');
  if (!q) { div.style.display='none'; return; }
  const todos=[];
  DATA.forEach(rota => { rota.passageiros.filter(p=>p.status==='ativo').forEach(p => {
    todos.push({nome:p.nome,bairro:p.bairro,cidade:p.cidade,linha:rota.linha,turno:rota.turno,telefone:p.telefone,endereco:p.embarque||p.endereco||''});
  }); });
  const found=todos.filter(p=>(p.nome||'').toLowerCase().includes(q)).slice(0,12);
  window._cadBuscaResultados=found;
  if (!found.length) { div.innerHTML='<div style="padding:12px;font-size:12px;color:var(--muted)">Nenhum resultado.</div>'; div.style.display='block'; return; }
  div.style.display='block'; div.innerHTML='';
  found.forEach((p,idx) => {
    const item=document.createElement('div');
    item.style.cssText='padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--border)';
    item.innerHTML='<div style="font-size:14px;font-weight:600">'+esc(p.nome)+'</div>'+'<div style="font-size:11px;color:var(--muted)">Linha '+p.linha+' · '+p.turno+' Turno'+(p.bairro?' · '+esc(p.bairro):'')+' </div>';
    item.addEventListener('click',function(){cadSelecionarPassageiro(idx);});
    div.appendChild(item);
  });
}

function cadSelecionarPassageiro(idx) {
  const p=window._cadBuscaResultados&&window._cadBuscaResultados[idx]; if(!p) return;
  CAD_PASSAGEIRO_SEL=p;
  document.getElementById('cadResultadoPass').style.display='none';
  document.getElementById('cadBuscaPass').value=p.nome;
  document.getElementById('cadPassSelecionado').style.display='block';
  document.getElementById('cadPassInfo').innerHTML=
    '<div style="font-weight:700;font-size:14px;margin-bottom:4px">'+esc(p.nome)+'</div>'+
    '<div style="font-size:12px;color:var(--muted)">Linha '+p.linha+' · '+p.turno+' Turno</div>'+
    (p.bairro?'<div style="font-size:12px;color:var(--muted)">'+esc(p.bairro)+(p.cidade?' · '+esc(p.cidade):'')+' </div>':'')+
    (p.endereco?'<div style="font-size:12px;color:var(--muted)">'+esc(p.endereco)+'</div>':'')+
    (p.telefone?'<div style="font-size:12px;color:var(--muted)">'+p.telefone+'</div>':'');
  const camposDiv=document.getElementById('cadCamposEspecificos');
  const hoje=hojeLocal();
  if (CAD_TIPO_KEY==='turno') {
    camposDiv.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:4px">
      <div><label class="form-label">Novo Turno *</label>
        <select class="form-input" id="cadNovoTurno"><option value="">— Selecione —</option><option value="1º Turno">1º Turno</option><option value="2º Turno">2º Turno</option><option value="3º Turno">3º Turno</option></select></div>
      <div><label class="form-label">A partir de *</label><input class="form-input" type="date" id="cadAPartirDe" value="${hoje}"></div>
    </div>`;
  } else if (CAD_TIPO_KEY==='endereco') {
    camposDiv.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:4px">
      <div style="grid-column:1/-1"><label class="form-label">Novo Endereço *</label><input class="form-input" id="cadNovoEndereco" placeholder="Rua, número, referência"></div>
      <div><label class="form-label">Bairro</label><input class="form-input" id="cadNovoBairro"></div>
      <div><label class="form-label">Cidade</label><input class="form-input" id="cadNovaCidade" value="${esc(p.cidade||'Sorocaba')}"></div>
      <div><label class="form-label">A partir de *</label><input class="form-input" type="date" id="cadAPartirDe" value="${hoje}"></div>
    </div>`;
  } else if (CAD_TIPO_KEY==='desligamento') {
    camposDiv.innerHTML=`<div style="margin-top:4px">
      <label class="form-label">Desligar a partir de *</label>
      <input class="form-input" type="date" id="cadAPartirDe" value="${hoje}">
      <div style="margin-top:10px;background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.2);border-radius:8px;padding:12px;font-size:12px;color:var(--muted)">O passageiro será retirado do transporte a partir da data informada.</div>
    </div>`;
  }
}

function cadValidarEtapa2() {
  if (CAD_TIPO_KEY==='novo') {
    if (!(document.getElementById('cadNome')||{}).value.trim()) { alert('Informe o nome completo.'); return false; }
    if (!(document.getElementById('cadTurno')||{}).value) { alert('Selecione o turno.'); return false; }
    if (!(document.getElementById('cadInicio')||{}).value) { alert('Informe a data de início.'); return false; }
  } else {
    if (!CAD_PASSAGEIRO_SEL) { alert('Selecione um passageiro.'); return false; }
    const ap=document.getElementById('cadAPartirDe');
    if (ap&&!ap.value) { alert('Informe a data.'); return false; }
    if (CAD_TIPO_KEY==='turno'&&!(document.getElementById('cadNovoTurno')||{}).value) { alert('Selecione o novo turno.'); return false; }
    if (CAD_TIPO_KEY==='endereco'&&!(document.getElementById('cadNovoEndereco')||{}).value.trim()) { alert('Informe o novo endereço.'); return false; }
  }
  cadColetarDados(); return true;
}

// Os turnos sao os que o gestor cadastrou. Lista fixa aqui significa
// que todo turno novo fica invisivel para quem abre a solicitacao.
// Para onde vai a solicitacao. Sem nada cadastrado, nao inventa nome de
// transportadora: diz o que de fato acontece.
function cadDestinoTexto() {
  const e = (typeof EMPRESA_CONFIG !== 'undefined' && EMPRESA_CONFIG) || {};
  const alvo = String(e.emailSolicitacoes || '').trim();
  if (alvo) return 'E-mail enviado para ' + alvo + '.';
  const nome = String(e.nome || '').trim();
  return nome ? ('Solicita\u00e7\u00e3o registrada para ' + nome + '.')
              : 'Solicita\u00e7\u00e3o registrada.';
}

// Com numero cadastrado o WhatsApp abre direto na conversa certa; sem
// ele, abre o seletor de contato, como antes.
function cadWhatsUrl(texto) {
  const e = (typeof EMPRESA_CONFIG !== 'undefined' && EMPRESA_CONFIG) || {};
  const num = String(e.whatsSolicitacoes || '').replace(/\D/g, '');
  return num ? ('https://wa.me/55' + num + '?text=' + texto)
             : ('https://wa.me/?text=' + texto);
}

function cadOpcoesTurno() {
  const nomes = (Array.isArray(TURNOS) && TURNOS.length)
    ? TURNOS.map(t => t && t.nome).filter(Boolean)
    : Object.keys(TURNOS_CHEGADA || {});
  const lista = nomes.length ? nomes : ['1º Turno', '2º Turno', '3º Turno'];
  return '<option value="">— Selecione —</option>' +
    lista.map(n => '<option value="' + n + '">' + n + '</option>').join('');
}

function cadColetarDados() {
  if (CAD_TIPO_KEY==='novo') {
    CAD_DADOS={nome:(document.getElementById('cadNome')||{}).value||'',telefone:(document.getElementById('cadTelefone')||{}).value||'',matricula:(document.getElementById('cadMatricula')||{}).value||'',endereco:(document.getElementById('cadEndereco')||{}).value||'',bairro:(document.getElementById('cadBairro')||{}).value||'',cidade:(document.getElementById('cadCidade')||{}).value||'',turno:(document.getElementById('cadTurno')||{}).value||'',inicio:(document.getElementById('cadInicio')||{}).value||''};
  } else {
    const ap=document.getElementById('cadAPartirDe');
    CAD_DADOS={passageiro:CAD_PASSAGEIRO_SEL,aPartirDe:ap?ap.value:''};
    if (CAD_TIPO_KEY==='turno') CAD_DADOS.novoTurno=(document.getElementById('cadNovoTurno')||{}).value||'';
    if (CAD_TIPO_KEY==='endereco') { CAD_DADOS.novoEndereco=(document.getElementById('cadNovoEndereco')||{}).value||''; CAD_DADOS.novoBairro=(document.getElementById('cadNovoBairro')||{}).value||''; CAD_DADOS.novaCidade=(document.getElementById('cadNovaCidade')||{}).value||''; }
  }
}

function cadMontarResumo() {
  const div=document.getElementById('cadResumo');
  let html='<div style="display:flex;flex-direction:column;gap:8px">';
  html+='<div><span style="color:var(--muted);font-size:11px">TIPO</span><br><strong>'+CAD_TIPO_LABEL+'</strong></div>';
  if (CAD_TIPO_KEY==='novo') {
    const d=CAD_DADOS;
    html+='<div><span style="color:var(--muted);font-size:11px">NOME</span><br><strong>'+esc(d.nome)+'</strong></div>';
    if (d.telefone) html+='<div><span style="color:var(--muted);font-size:11px">TELEFONE</span><br><strong>'+d.telefone+'</strong></div>';
    if (d.matricula) html+='<div><span style="color:var(--muted);font-size:11px">MATRÍCULA</span><br><strong>'+d.matricula+'</strong></div>';
    if (d.endereco) html+='<div><span style="color:var(--muted);font-size:11px">ENDEREÇO</span><br><strong>'+esc(d.endereco)+(d.bairro?' · '+esc(d.bairro):'')+(d.cidade?' · '+esc(d.cidade):'')+' </strong></div>';
    html+='<div><span style="color:var(--muted);font-size:11px">TURNO</span><br><strong>'+d.turno+'</strong></div>';
    html+='<div><span style="color:var(--muted);font-size:11px">INÍCIO</span><br><strong>'+new Date(d.inicio+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})+'</strong></div>';
  } else {
    const p=CAD_DADOS.passageiro||{};
    html+='<div><span style="color:var(--muted);font-size:11px">PASSAGEIRO</span><br><strong>'+esc(p.nome||'')+'</strong><br><span style="font-size:12px;color:var(--muted)">Linha '+p.linha+' · '+p.turno+' Turno</span></div>';
    if (CAD_TIPO_KEY==='turno') html+='<div><span style="color:var(--muted);font-size:11px">TURNO ATUAL → NOVO</span><br><strong>'+p.turno+' → '+CAD_DADOS.novoTurno+'</strong></div>';
    if (CAD_TIPO_KEY==='endereco') html+='<div><span style="color:var(--muted);font-size:11px">NOVO ENDEREÇO</span><br><strong>'+esc(CAD_DADOS.novoEndereco||'')+(CAD_DADOS.novoBairro?' · '+esc(CAD_DADOS.novoBairro):'')+' </strong></div>';
    if (CAD_DADOS.aPartirDe) html+='<div><span style="color:var(--muted);font-size:11px">A PARTIR DE</span><br><strong>'+new Date(CAD_DADOS.aPartirDe+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})+'</strong></div>';
  }
  div.innerHTML=html+'</div>';
}

function cadMontarResumoTexto() {
  if (CAD_TIPO_KEY==='novo') {
    const d=CAD_DADOS;
    return 'Nome: '+d.nome+'\nTelefone: '+(d.telefone||'—')+'\nMatricula: '+(d.matricula||'—')+'\nEndereco: '+(d.endereco||'—')+(d.bairro?' - '+d.bairro:'')+(d.cidade?' - '+d.cidade:'')+'\nTurno: '+d.turno+'\nInicio: '+(d.inicio?new Date(d.inicio+'T12:00:00').toLocaleDateString('pt-BR'):'—');
  } else {
    const p=CAD_DADOS.passageiro||{};
    let txt='Passageiro: '+(p.nome||'')+' (Linha '+(p.linha||'')+' - '+(p.turno||'')+' Turno)';
    if (CAD_TIPO_KEY==='turno') txt+='\nNovo Turno: '+(CAD_DADOS.novoTurno||'');
    if (CAD_TIPO_KEY==='endereco') txt+='\nNovo Endereco: '+(CAD_DADOS.novoEndereco||'')+(CAD_DADOS.novoBairro?' - '+CAD_DADOS.novoBairro:'');
    if (CAD_DADOS.aPartirDe) txt+='\nA partir de: '+new Date(CAD_DADOS.aPartirDe+'T12:00:00').toLocaleDateString('pt-BR');
    return txt;
  }
}

async function cadEnviar() {
  const obs=document.getElementById('cadObs').value.trim();
  const msg=document.getElementById('cadMsg');
  msg.style.color='var(--muted)'; msg.textContent='Enviando...';
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) throw new Error('Firebase indisponível');
    const {getDoc,setDoc,doc}=await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref=doc(fbDb,CLIENTE_ID,CAD_FB_KEY);
    const snap=await getDoc(ref);
    const lista=(snap.exists()&&snap.data().lista)?snap.data().lista:[];
    const now=new Date();
    const pad=n=>String(n).padStart(2,'0');
    const idBase='CAD-'+now.getFullYear()+pad(now.getMonth()+1)+pad(now.getDate());
    const id=idBase+'-'+String(lista.filter(s=>s.id.startsWith(idBase)).length+1).padStart(3,'0');
    const limpar=obj=>JSON.parse(JSON.stringify(obj,(k,v)=>v===undefined?'':v));
    const nova=limpar({id,tipo:CAD_TIPO_KEY,tipoLabel:CAD_TIPO_LABEL,dados:CAD_DADOS,obs,status:'pendente',criadoEm:now.toISOString(),mesRef:mesLocal(now)});
    lista.push(nova);
    await setDoc(ref,{lista:lista.map(limpar),updatedAt:now.toISOString()});
    try {
      emailjs.init('i8-o88nerwgYStDgL');
      const resumoTxt=cadMontarResumoTexto();
      for (const email of ['redentorfretamento@gmail.com','borbacana@gmail.com']) {
        await emailjs.send('service_gp46qeg','template_m4k9byn',{ origem: C.origemEmail,sol_id:id,tipo:CAD_TIPO_LABEL,data:now.toLocaleDateString('pt-BR'),horario:now.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),roteiro:'—',funcionarios:resumoTxt,obs:obs||'—',to_email:email});
      }
    } catch(e){console.warn('CAD email:',e);}
    const waTexto=encodeURIComponent('Solicitacao de Cadastro - ' + (EMPRESA_CONFIG.nome || 'Transportadora') + '\n\nID: '+id+'\nTipo: '+CAD_TIPO_LABEL+'\n'+cadMontarResumoTexto()+(obs?'\n\nObs: '+obs:'')+'\n\nAguardo atendimento.');
    msg.innerHTML='<div style="background:rgba(59,130,246,0.1);border:1px solid rgba(59,130,246,0.3);border-radius:12px;padding:16px;margin-top:8px;text-align:left"><div style="font-weight:700;font-size:15px;color:var(--accent2);margin-bottom:8px">Solicitação enviada!</div><div style="font-size:13px;margin-bottom:4px"><strong>'+id+'</strong></div><div style="font-size:12px;color:var(--muted);margin-bottom:14px">' + cadDestinoTexto() + '</div><a href="'+cadWhatsUrl(waTexto)+'" target="_blank" style="display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;background:#25D366;color:#fff;border-radius:10px;text-decoration:none;font-family:Barlow,sans-serif;font-weight:800;font-size:14px;margin-bottom:10px">Compartilhar pelo WhatsApp</a><button onclick="cadNovaSolicitacao()" style="width:100%;padding:11px;border-radius:10px;border:1px solid var(--border);background:transparent;color:var(--text);font-size:14px;cursor:pointer;font-family:Barlow,sans-serif;font-weight:700">Nova Solicitação</button></div>';
  } catch(e) { msg.style.color='var(--red)'; msg.textContent='Erro: '+e.message; }
}

function cadNovaSolicitacao() {
  CAD_TIPO_KEY=''; CAD_TIPO_LABEL=''; CAD_DADOS={}; CAD_PASSAGEIRO_SEL=null;
  document.querySelectorAll('#cadEtapa1 .cli-tipo-btn').forEach(b=>b.classList.remove('selected'));
  document.getElementById('cadObs').value='';
  document.getElementById('cadMsg').innerHTML='';
  cadGoEtapa(1);
}

async function cadCarregarHistorico() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) return;
    const {onSnapshot,doc}=await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    onSnapshot(doc(fbDb,CLIENTE_ID,CAD_FB_KEY),snap=>{
      CAD_SOL_DADOS=(snap.exists()&&snap.data().lista)?snap.data().lista:[];
      if (document.getElementById('cadAbaHistorico').style.display!=='none') cadRenderHistorico();
    });
  } catch(e){console.warn('CAD hist:',e);}
}

function cadRenderHistorico() {
  const filtroStatus=document.getElementById('cadFiltroStatus').value;
  const filtroMes=document.getElementById('cadFiltroMes').value;
  let lista=(CAD_SOL_DADOS||[]).filter(s=>(!filtroStatus||s.status===filtroStatus)&&(!filtroMes||s.mesRef===filtroMes)).sort((a,b)=>(b.criadoEm||'').localeCompare(a.criadoEm||''));
  const div=document.getElementById('cadListaHistorico');
  if (!lista.length){div.innerHTML='<div style="text-align:center;padding:32px;color:var(--muted)">Nenhuma solicitação.</div>';return;}
  const corTipo={novo:'#3b82f6',turno:'#f59e0b',endereco:'#10b981',desligamento:'#ef4444'};
  div.innerHTML=lista.map(s=>{
    const cor=corTipo[s.tipo]||'#6b7280';
    const stLabel=s.status==='atendida'?'Atendida':'Pendente';
    const stCor=s.status==='atendida'?'#6b7280':'#f59e0b';
    const d=s.dados||{}; let detalhe='';
    if (s.tipo==='novo') detalhe=esc(d.nome||'')+' · '+(d.turno||'')+(d.inicio?' · Início: '+new Date(d.inicio+'T12:00:00').toLocaleDateString('pt-BR'):'');
    else if (d.passageiro){detalhe=esc(d.passageiro.nome||'');if(s.tipo==='turno')detalhe+=' → '+(d.novoTurno||'');if(s.tipo==='endereco')detalhe+=' · '+esc(d.novoEndereco||'');if(d.aPartirDe)detalhe+=' · a partir de '+new Date(d.aPartirDe+'T12:00:00').toLocaleDateString('pt-BR');}
    return '<div style="border:1px solid var(--border);border-left:4px solid '+cor+';border-radius:10px;padding:12px 14px;margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:4px"><div><span style="font-size:11px;color:var(--muted);font-weight:700;font-family:Barlow,sans-serif">'+s.id+'</span><span style="background:'+stCor+'22;color:'+stCor+';border:1px solid '+stCor+'55;border-radius:6px;padding:1px 8px;font-size:11px;font-weight:700;margin-left:8px">'+stLabel+'</span></div><div style="font-size:10px;color:var(--muted)">'+new Date(s.criadoEm||Date.now()).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+'</div></div><div style="font-weight:700;font-size:14px">'+s.tipoLabel+'</div><div style="font-size:12px;color:var(--muted)">'+detalhe+'</div>'+(s.obs?'<div style="font-size:12px;color:var(--muted);margin-top:2px">'+esc(s.obs)+'</div>':'')+'</div>';
  }).join('');
}
