// ===== AVISOS AOS PASSAGEIROS (Gestor DSV) =====
let AV_LISTA = [];
function openAvisos() {
  try { cliMarcarNav('Avisos'); } catch (e) {}
  const sel = document.getElementById('avDestino');
  sel.innerHTML = '<option value="">Todas as linhas (aviso geral)</option>';
  DATA.forEach(r => {
    const chave = String(r.linha) + '_' + r.turno;
    const opt = document.createElement('option');
    opt.value = chave; opt.textContent = 'Linha ' + r.linha + ' — ' + r.turno + ' Turno';
    sel.appendChild(opt);
  });
  document.getElementById('modalAvisos').classList.add('open');
  avCarregar();
}
async function avCarregar() {
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const snap = await getDoc(doc(fbDb, CLIENTE_ID, 'avisos'));
    AV_LISTA = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
  } catch(e) { AV_LISTA = []; }
  avRender();
}
function avRender() {
  const div = document.getElementById('avLista');
  if (!AV_LISTA.length) { div.innerHTML = '<div style="text-align:center;color:var(--muted);padding:20px">Nenhum aviso publicado.</div>'; return; }
  const ord = [...AV_LISTA].sort((a,b)=>(b.em||'').localeCompare(a.em||''));
  div.innerHTML = ord.map(a => {
    const data = a.em ? new Date(a.em).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : '';
    const dest = a.chave ? ('Linha ' + a.chave.replace('_',' — ') + ' Turno') : 'Todas as linhas';
    return '<div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid ' + (a.tipo==='pdf'?'var(--accent2)':'var(--accent)') + ';border-radius:10px;padding:12px;margin-bottom:10px">' +
      '<div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:5px"><span>' + esc(a.autor||'Gestor') + ' · ' + esc(dest) + '</span><span>' + data + '</span></div>' +
      '<div style="font-size:13px;margin-bottom:8px">' + esc(a.txt) + (a.link?' ':'') + '</div>' +
      '<button class="export-btn" style="font-size:11px;color:var(--red);border-color:var(--red)" onclick="avExcluir(\'' + a.id + '\')">Excluir</button>' +
    '</div>';
  }).join('');
}
async function avPublicar() {
  const txt = document.getElementById('avTexto').value.trim();
  const link = document.getElementById('avLink').value.trim();
  const tipo = document.getElementById('avTipo').value;
  const chave = document.getElementById('avDestino').value;
  if (!txt && !link) { alert('Escreva uma mensagem ou cole um link.'); return; }
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'avisos');
    const snap = await getDoc(ref);
    let lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    lista.push({ id:'AV-'+Date.now().toString(36), chave: chave||'', tipo, txt: txt||(tipo==='pdf'?'Documento disponível':'Aviso'), link: link||'', autor:'Gestor DSV', em:new Date().toISOString() });
    if (lista.length > 100) lista = lista.slice(-100);
    await setDoc(ref, { lista, updatedAt:new Date().toISOString() });
    document.getElementById('avTexto').value=''; document.getElementById('avLink').value='';
    AV_LISTA = lista; avRender();
    alert('Aviso publicado! Os passageiros já podem ver no app.');
  } catch(e) { alert('Erro ao publicar: ' + e.message); }
}
async function avExcluir(id) {
  if (!confirm('Excluir este aviso?')) return;
  try {
    if (!fbDb) await initFirebase();
    const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    AV_LISTA = AV_LISTA.filter(a => a.id !== id);
    await setDoc(doc(fbDb, CLIENTE_ID, 'avisos'), { lista: AV_LISTA, updatedAt:new Date().toISOString() });
    avRender();
  } catch(e) { alert('Erro: ' + e.message); }
}

// ===== CHATS DAS LINHAS (Gestor DSV) =====
const GESTOR_NOME = 'Gestor DSV';
let _chatUnsub = null, _chatChaveAtual = null;
function openChats() {
  try { cliMarcarNav('Chats'); } catch (e) {}
  const sel = document.getElementById('chatSelLinha');
  sel.innerHTML = '<option value="">— Selecione —</option>';
  DATA.forEach(r => {
    const chave = String(r.linha) + '_' + r.turno;
    const opt = document.createElement('option');
    opt.value = chave; opt.textContent = 'Linha ' + r.linha + ' — ' + r.turno + ' Turno';
    sel.appendChild(opt);
  });
  document.getElementById('chatsSeletor').style.display = 'block';
  document.getElementById('chatsConversa').style.display = 'none';
  document.getElementById('modalChats').classList.add('open');
}
function chatsFechar() { if (_chatUnsub){_chatUnsub();_chatUnsub=null;} document.getElementById('modalChats').classList.remove('open'); }
function chatVoltarSeletor() { if (_chatUnsub){_chatUnsub();_chatUnsub=null;} document.getElementById('chatsSeletor').style.display='block'; document.getElementById('chatsConversa').style.display='none'; }
function chatDocId(chave) { return 'chat_' + chave.replace('°','').replace(/[^a-zA-Z0-9_]/g,''); }
async function chatAbrirLinha() {
  const chave = document.getElementById('chatSelLinha').value;
  if (!chave) return;
  _chatChaveAtual = chave;
  document.getElementById('chatsSeletor').style.display = 'none';
  document.getElementById('chatsConversa').style.display = 'flex';
  document.getElementById('chatTituloLinha').textContent = 'Linha ' + chave.replace('_',' — ') + ' Turno';
  try {
    if (!fbDb) await initFirebase();
    const { doc, onSnapshot } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    if (_chatUnsub) _chatUnsub();
    _chatUnsub = onSnapshot(doc(fbDb, CLIENTE_ID, chatDocId(chave)), (snap) => {
      const msgs = (snap.exists() && snap.data().msgs) ? snap.data().msgs : [];
      chatGestorRender(msgs);
    });
  } catch(e) { console.warn('chat:', e); }
}
function chatGestorRender(msgs) {
  const box = document.getElementById('chatGestorMsgs');
  if (!box) return;
  const cab = '<div style="align-self:center;color:var(--muted);font-size:12px;text-align:center">— Chat da Linha ' + _chatChaveAtual.replace('_',' · ') + ' Turno —</div>';
  box.innerHTML = cab + msgs.map((m, _i, _arr) => {
    const ehGestor = m.tipo === 'gestor';
    const cor = m.tipo === 'gestor' ? 'rgba(245,158,11,0.15)' : m.tipo === 'motorista' ? 'rgba(59,130,246,0.15)' : 'var(--surface3)';
    const align = ehGestor ? 'flex-end' : 'flex-start';
    let inner = '';
    if (m.autor) inner += '<div style="font-size:10px;font-weight:700;color:var(--muted);margin-bottom:2px">' + esc(m.autor) + '</div>';
    if (m.tipo === 'loc') inner += '' + esc(m.txt) + (m.link ? ' <a href="'+esc(m.link)+'" target="_blank" style="color:var(--green)">abrir</a>' : '');
    else inner += esc(m.txt);
    if (m.hora) inner += '<div style="font-size:9px;color:var(--muted);text-align:right;margin-top:2px">' + m.hora + '</div>';
    var _sep = _sepDataChat(m, _i > 0 ? _arr[_i-1] : null);
    return _sep + '<div style="align-self:' + align + ';max-width:80%;background:' + cor + ';border-radius:12px;padding:8px 11px;font-size:13px">' + inner + '</div>';
  }).join('');
  box.scrollTop = box.scrollHeight;
}
async function chatGestorEnviar() {
  const inp = document.getElementById('chatGestorInput');
  const txt = inp.value.trim();
  if (!txt || !_chatChaveAtual) return;
  inp.value = '';
  try {
    if (!fbDb) await initFirebase();
    const { doc, getDoc, setDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, chatDocId(_chatChaveAtual));
    const snap = await getDoc(ref);
    let msgs = (snap.exists() && snap.data().msgs) ? snap.data().msgs : [];
    const hora = String(new Date().getHours()).padStart(2,'0') + ':' + String(new Date().getMinutes()).padStart(2,'0');
    msgs.push({ tipo:'gestor', autor: GESTOR_NOME, txt, hora, em:new Date().toISOString() });
    if (msgs.length > 200) msgs = msgs.slice(-200);
    await setDoc(ref, { msgs, updatedAt:new Date().toISOString() });
  } catch(e) { inp.value = txt; alert('Erro ao enviar.'); }
}

// ===== RECLAMAÇÕES / OCORRÊNCIAS (Gestor DSV) =====
let RC_LISTA = [];
const RC_STATUS = {
  aberta:        { lbl:'Aberta', cor:'#3b82f6' },
  respondida:    { lbl:'Respondida', cor:'#f59e0b' },
  resolvida:     { lbl:'Resolvida', cor:'#10b981' },
  nao_resolvida: { lbl:'Não resolvida', cor:'#ef4444' },
  improcedente:  { lbl:'Improcedente', cor:'#9aa0a6' }
};

function openReclamacoes() {
  try { cliMarcarNav('Reclamações'); } catch (e) {}
  const sel = document.getElementById('rcLinha');
  sel.innerHTML = '<option value="">—</option>';
  DATA.forEach(r => {
    const opt = document.createElement('option');
    opt.value = String(r.linha) + '_' + r.turno;
    opt.textContent = 'Linha ' + r.linha + ' — ' + r.turno;
    sel.appendChild(opt);
  });
  document.getElementById('rcData').value = hojeLocal();
  document.getElementById('modalReclamacoes').classList.add('open');
  rcCarregar();
}

async function rcCarregar() {
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const snap = await getDoc(doc(fbDb, CLIENTE_ID, 'reclamacoes'));
    RC_LISTA = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
  } catch(e) { RC_LISTA = []; }
  rcRender();
}

function rcInteracoes(r) {
  // compatibilidade: se não tiver interacoes, monta a partir dos campos antigos
  if (r.interacoes && r.interacoes.length) return r.interacoes;
  const arr = [{ de:'dsv', tipo:'abertura', texto:r.descricao, provas:r.provas||'', em:r.em }];
  if (r.resposta) arr.push({ de:'redentor', tipo:'resposta', texto:r.resposta, provas:r.provasResposta||'', em:r.dataResposta||r.em });
  return arr;
}

function rcRenderHistorico(r) {
  const inter = rcInteracoes(r);
  return inter.map(m => {
    const ehDsv = m.de === 'dsv';
    const cor = ehDsv ? 'rgba(59,130,246,0.12)' : 'rgba(245,158,11,0.12)';
    const align = ehDsv ? 'flex-start' : 'flex-end';
    const autor = ehDsv ? 'Gestor DSV' : 'Redentor';
    const corAutor = ehDsv ? '#3b82f6' : '#f59e0b';
    let tag = '';
    if (m.tipo === 'recusa') tag = ' <span style="color:#ef4444;font-weight:700">· Não resolveu</span>';
    else if (m.tipo === 'aceite') tag = ' <span style="color:#10b981;font-weight:700">· Aceitou</span>';
    else if (m.tipo === 'improcedente') tag = ' <span style="color:#9aa0a6;font-weight:700">· Improcedente</span>';
    const dt = m.em ? new Date(m.em).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : '';
    let inner = '<div style="font-size:10px;font-weight:700;color:'+corAutor+';margin-bottom:3px">'+autor+tag+'</div>';
    inner += '<div style="font-size:13px;color:var(--text)">'+esc(m.texto)+'</div>';
    if (m.provas) inner += '<div style="font-size:11px;margin-top:4px"><a href="'+esc(m.provas)+'" target="_blank" style="color:var(--accent2)">provas</a></div>';
    if (dt) inner += '<div style="font-size:9px;color:var(--muted);text-align:right;margin-top:3px">'+dt+'</div>';
    return '<div style="align-self:'+align+';max-width:88%;background:'+cor+';border-radius:10px;padding:9px 11px;margin-bottom:6px">'+inner+'</div>';
  }).join('');
}

function rcRender() {
  const div = document.getElementById('rcLista');
  const filtro = document.getElementById('rcFiltroStatus').value;
  let lista = [...RC_LISTA].sort((a,b)=>(b.em||'').localeCompare(a.em||''));
  if (filtro) lista = lista.filter(r => (r.status||'aberta') === filtro);
  if (!lista.length) { div.innerHTML = '<div style="text-align:center;color:var(--muted);padding:20px">Nenhuma ocorrência.</div>'; return; }
  div.innerHTML = lista.map(r => {
    const st = RC_STATUS[r.status||'aberta'];
    const dataOc = r.dataOcorrencia ? r.dataOcorrencia.split('-').reverse().join('/') : '—';
    const alvo = r.passageiro ? esc(r.passageiro) : (r.chave ? 'Linha ' + r.chave.replace('_',' — ') : 'Geral');
    let h = '<div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid '+st.cor+';border-radius:10px;padding:14px;margin-bottom:12px">';
    h += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:8px"><span style="font-weight:700;font-size:13px;color:'+st.cor+'">'+st.lbl+'</span><span style="font-size:11px;color:var(--muted)">Ocorrência: '+dataOc+'</span></div>';
    h += '<div style="font-size:13px;margin-bottom:10px"><b>'+esc(alvo)+'</b>'+(r.turno?' · '+r.turno+' turno':'')+'</div>';
    // Histórico tipo chat
    h += '<div style="display:flex;flex-direction:column;background:var(--bg);border-radius:10px;padding:10px;margin-bottom:8px">'+rcRenderHistorico(r)+'</div>';
    // Ações do DSV: só quando a Redentor já respondeu (respondida) e ainda não foi resolvida
    if (r.status === 'respondida') {
      h += '<div style="display:flex;gap:8px;margin-top:6px;flex-wrap:wrap">';
      h += '<button onclick="rcAceitar(\''+r.id+'\')" style="flex:1;background:rgba(16,185,129,0.15);color:#10b981;border:1px solid #10b981;border-radius:8px;padding:8px;font-size:12px;font-weight:700;cursor:pointer">Aceitar (Resolvida)</button>';
      h += '<button onclick="rcRecusar(\''+r.id+'\')" style="flex:1;background:rgba(239,68,68,0.15);color:#ef4444;border:1px solid #ef4444;border-radius:8px;padding:8px;font-size:12px;font-weight:700;cursor:pointer">Não resolveu</button>';
      h += '</div>';
    } else if (r.status === 'aberta') {
      h += '<div style="font-size:12px;color:var(--muted);font-style:italic">Aguardando resposta da Redentor...</div>';
    } else if (r.status === 'nao_resolvida') {
      h += '<div style="font-size:12px;color:#ef4444;font-style:italic">Aguardando nova resposta da Redentor...</div>';
    }
    h += '<button onclick="rcExcluir(\''+r.id+'\')" style="background:none;border:none;color:var(--red);font-size:11px;cursor:pointer;margin-top:8px;padding:0">Excluir</button>';
    h += '</div>';
    return h;
  }).join('');
}

async function rcRegistrar() {
  const desc = document.getElementById('rcDescricao').value.trim();
  if (!desc) { alert('Descreva a ocorrência.'); return; }
  const reg = {
    id: 'RC-' + Date.now().toString(36),
    dataOcorrencia: document.getElementById('rcData').value || hojeLocal(),
    chave: document.getElementById('rcLinha').value || '',
    turno: document.getElementById('rcTurno').value || '',
    passageiro: document.getElementById('rcPassageiro').value.trim() || '',
    descricao: desc,
    provas: document.getElementById('rcProvas').value.trim() || '',
    interacoes: [{ de:'dsv', tipo:'abertura', texto: desc, provas: document.getElementById('rcProvas').value.trim() || '', em: new Date().toISOString() }],
    status: 'aberta',
    em: new Date().toISOString()
  };
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'reclamacoes');
    const snap = await getDoc(ref);
    let lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    lista.push(reg);
    await setDoc(ref, { lista, updatedAt: new Date().toISOString() });
    RC_LISTA = lista;
    // limpar form
    document.getElementById('rcDescricao').value = '';
    document.getElementById('rcProvas').value = '';
    document.getElementById('rcPassageiro').value = '';
    rcRender();
    // e-mail para Redentor
    try {
      emailjs.init('i8-o88nerwgYStDgL');
      const alvo = reg.passageiro || (reg.chave ? 'Linha '+reg.chave.replace('_',' — ') : 'Geral');
      await emailjs.send('service_gp46qeg','template_m4k9byn',{ origem: C.origemEmail,
        sol_id: reg.id, tipo:'Reclamação Aberta', data: reg.dataOcorrencia.split('-').reverse().join('/'),
        horario: new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}), roteiro: alvo + (reg.turno?' · '+reg.turno+' turno':''),
        funcionarios: reg.descricao, obs: reg.provas ? 'Provas: '+reg.provas : '—',
        to_email:'redentorfretamento@gmail.com'
      });
    } catch(e) { console.warn('email reclamação:', e); }
    alert('Ocorrência registrada! A Redentor foi notificada e vai responder.');
  } catch(e) { alert('Erro ao registrar: ' + e.message); }
}

async function rcAceitar(id) {
  if (!confirm('Aceitar a resposta e marcar como RESOLVIDA?')) return;
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'reclamacoes');
    const snap = await getDoc(ref);
    let lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    const r = lista.find(x => x.id === id);
    if (r) {
      r.status = 'resolvida';
      r.avaliadaEm = new Date().toISOString();
      if (!r.interacoes) r.interacoes = rcInteracoes(r);
      r.interacoes.push({ de:'dsv', tipo:'aceite', texto:'Resposta aceita. Ocorrência resolvida.', em:new Date().toISOString() });
    }
    await setDoc(ref, { lista, updatedAt: new Date().toISOString() });
    RC_LISTA = lista; rcRender();
  } catch(e) { alert('Erro: ' + e.message); }
}

async function rcRecusar(id) {
  const motivo = prompt('Por que você considera que NÃO foi resolvido?\n(obrigatório — explique para a Redentor)');
  if (motivo === null) return; // cancelou
  if (!motivo.trim()) { alert('É obrigatório informar o motivo.'); return; }
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const ref = doc(fbDb, CLIENTE_ID, 'reclamacoes');
    const snap = await getDoc(ref);
    let lista = (snap.exists() && snap.data().lista) ? snap.data().lista : [];
    const r = lista.find(x => x.id === id);
    if (r) {
      r.status = 'nao_resolvida';
      r.avaliadaEm = new Date().toISOString();
      if (!r.interacoes) r.interacoes = rcInteracoes(r);
      r.interacoes.push({ de:'dsv', tipo:'recusa', texto: motivo.trim(), em:new Date().toISOString() });
    }
    await setDoc(ref, { lista, updatedAt: new Date().toISOString() });
    RC_LISTA = lista; rcRender();
    // e-mail para Redentor com assunto "Reclamação Não resolvida"
    try {
      emailjs.init('i8-o88nerwgYStDgL');
      const alvo = r.passageiro || (r.chave ? 'Linha '+r.chave.replace('_',' — ') : 'Geral');
      await emailjs.send('service_gp46qeg','template_m4k9byn',{ origem: C.origemEmail,
        sol_id: r.id, tipo:'Reclamação Não resolvida', data: new Date().toLocaleDateString('pt-BR'),
        horario: new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),
        roteiro: alvo + (r.turno?' · '+r.turno+' turno':''),
        funcionarios: 'MOTIVO DA RECUSA: ' + motivo.trim(), obs:'A reclamação voltou para a Redentor responder novamente.',
        to_email:'redentorfretamento@gmail.com'
      });
    } catch(e) { console.warn('email recusa:', e); }
  } catch(e) { alert('Erro: ' + e.message); }
}

async function rcExcluir(id) {
  if (!confirm('Excluir esta ocorrência?')) return;
  try {
    if (!fbDb) await initFirebase();
    const { getDoc, setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    RC_LISTA = RC_LISTA.filter(r => r.id !== id);
    await setDoc(doc(fbDb, CLIENTE_ID, 'reclamacoes'), { lista: RC_LISTA, updatedAt: new Date().toISOString() });
    rcRender();
  } catch(e) { alert('Erro: ' + e.message); }
}

