MAPS_API_KEY = '';
// Show login on load
window.onload = () => {
  // Só mostra a tela de acesso se ninguém já tiver entrado (auto-entrada do
  // portal ou sessão do Firebase podem ter liberado antes deste evento).
  if (!window._clienteLiberado) {
    document.getElementById('loginOverlay').style.display = 'flex';
    setTimeout(() => { const c = document.getElementById('senhaCliente'); if (c) c.focus(); }, 300);
  }
  // Install banner
  const isStandalone = window.navigator.standalone || window.matchMedia('(display-mode: standalone)').matches;
  if (!isStandalone) {
    setTimeout(() => {
      const banner = document.getElementById('installBanner');
      const instructions = document.getElementById('installInstructions');
      if (!banner || !instructions) return;
      const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
      const isAndroid = /Android/i.test(navigator.userAgent);
      if (isIOS) { banner.style.display = 'flex'; instructions.textContent = 'Safari: toque em compartilhar ↑ → "Adicionar à Tela de Início"'; }
      else if (isAndroid) { banner.style.display = 'flex'; instructions.textContent = 'Chrome: toque nos 3 pontos ⋮ → "Adicionar à tela inicial"'; }
    }, 2500);
  }
};

